import {describe, expect, it} from 'vitest'
import {parseConfig, safeParseConfig} from './loader'

const minimal = {project: {name: 'acme'}, stackPack: {id: 'node'}}

describe('archeConfigSchema', () => {
    it('accepts a minimal config and applies opinionated defaults', () => {
        const config = parseConfig(minimal)

        expect(config.$schemaVersion).toBe(1)
        expect(config.project.name).toBe('acme')
        expect(config.project.humanInLead).toBe(true)
        expect(config.stackPack.version).toBe('latest')
    })

    it('defaults all providers to none (graceful degradation)', () => {
        const config = parseConfig(minimal)
        expect(config.providers.vcs.id).toBe('none')
        expect(config.providers.pm.id).toBe('none')
        expect(config.providers.wiki.id).toBe('none')
    })

    it('defaults to the GitFlow-ish branch model', () => {
        const {branchModel} = parseConfig(minimal)
        expect(branchModel.trunk).toBe('main')
        expect(branchModel.integration).toBe('develop')
        expect(branchModel.agentForbiddenBranches).toEqual(['main', 'develop'])
    })

    it('turns every extension primitive on by default (full v1) except the shared brain', () => {
        const {primitives} = parseConfig(minimal)
        expect(primitives.livingMemory).toBe(true)
        expect(primitives.ciWorkflows).toBe(true)
        expect(primitives.codeowners).toBe(true)
