/**
 * The virtual-file primitives shared by the engine, providers, and packs.
 *
 * A {@link VirtualFile} is a rendered artifact that has not yet touched disk. Its
 * {@link MergePolicy} and {@link FileOwner} are what make brownfield scaffolding safe:
 * the engine consults them to decide whether a write creates, replaces, merges a region,
 * or surfaces a conflict.
 */

/** Who authored a file — drives conflict detection and the update/migration story. */
export type FileOwner =
    | 'base' // @arche/templates-base (tech-agnostic governance)
    | 'arche' // synthesized by the engine (e.g. composed rule docs)
    | 'user' // the human owns it; Arche must never clobber
    | `pack:${string}` // a stack pack
    | `provider:${string}` // a provider adapter (e.g. CODEOWNERS)

/** How the engine reconciles a rendered file against what is already on disk. */
export type MergePolicy =
    | 'replace' // Arche owns the whole file; 3-way protected against user edits
    | 'create-if-absent' // write once; never touch again if it exists
    | 'managed-region' // Arche owns only the text between region markers
    | 'three-way' // full 3-way merge (alias of replace's conflict semantics)
    | 'append-once' // append the payload once, if not already present

/** The begin/end sentinel lines that delimit an Arche-managed region within a user file. */
export interface RegionMarker {
    begin: string
    end: string
}

/** A rendered file that has not yet been written to disk. */
export interface VirtualFile {
    /** Repo-relative POSIX path. */
    path: string
    contents: string
    owner: FileOwner
    merge: MergePolicy
    /** Required when `merge` is `managed-region`. */
    region?: RegionMarker
    /** Set the executable bit on write (e.g. git hooks). */
    executable?: boolean
}

