import type {RegionMarker} from './files'

export const DEFAULT_REGION_ID = 'arche'

/** Managed-region markers using `#` line comments (YAML, .env, shell, gitignore). */
export function hashRegion(id: string = DEFAULT_REGION_ID): RegionMarker {
    return {begin: `# >>> ${id}:managed`, end: `# <<< ${id}:managed`}
}

/** Managed-region markers using HTML comments (Markdown, HTML). */
export function htmlRegion(id: string = DEFAULT_REGION_ID): RegionMarker {
    return {begin: `<!-- >>> ${id}:managed -->`, end: `<!-- <<< ${id}:managed -->`}
}

/** Managed-region markers using `//` line comments (TS/JS/JSON5). */
export function slashRegion(id: string = DEFAULT_REGION_ID): RegionMarker {
    return {begin: `// >>> ${id}:managed`, end: `// <<< ${id}:managed`}
}

