/**
 * Provider-primitive types shared across the provider SDK, concrete adapters, and the
 * engine. Kept in the kernel (rather than the provider SDK) so that a file-emitting
 * provider and the engine can both reference {@link VirtualFile} + {@link ActionResult}
 * without importing the full provider contract.
 */

export type ProviderKind = 'vcs' | 'pm' | 'wiki'

/**
 * A capability a provider declares it can perform (e.g. `'codeowners'`,
 * `'branch-protection'`, `'labels'`, `'teams'`, `'story-linking'`). Kept as a string so
 * third-party providers can declare capabilities Arche core does not know about.
 */
export type Capability = string

/** The outcome of a server-side provider action (branch protection, team creation, …). */
export type ActionStatus =
    | 'applied' // the change was made
    | 'unchanged' // already in the desired state
    | 'skipped' // intentionally not attempted
    | 'unsupported' // the provider cannot do this
    | 'unauthenticated' // no credentials; see `manualSteps`
    | 'failed' // attempted and errored

export interface ActionResult {
    /** Human-readable action id, e.g. `'ensureBranchProtection(main)'`. */
    action: string
    status: ActionStatus
    detail?: string
    /** Emitted when `unauthenticated`/`unsupported`: exact commands a human must run. */
    manualSteps?: string[]
}

