import type {ActionResult, Capability, ProviderKind, VirtualFile} from '@arche/kernel'
import type {ArcheConfig, TierModel} from '@arche/schema'

/**
 * The provider abstraction. Providers are capability-based: the engine asks a provider
 * whether it can do X and either calls it or degrades to emitted manual steps. This is how
 * "pluggable from day one" survives shipping with only GitHub implemented.
 *
 * Two distinct action kinds, mirroring the hardest-won lesson of the reference repo:
 * - **File artifacts** (`emit*`) — returned as {@link VirtualFile}s, written by the engine.
 *   These are advisory (a CI guard is just a comment-poster).
 * - **Server-side actions** (`ensure*`) — the *real* enforcement gate (branch protection,
 *   code-owner review). May report `unauthenticated`/`unsupported` and hand back manual steps.
 */

export interface ProviderMeta {
    id: string
    kind: ProviderKind
    capabilities: ReadonlySet<Capability>
}

export interface ProviderContext {
    config: ArcheConfig
    /** Target repo root. */
    cwd: string
}

export interface BranchProtectionRule {
    /** Branch name or pattern (e.g. `main`, `release/*`). */
    branch: string
    requireCodeOwnerReview: boolean
    requiredApprovals: number
    requiredStatusChecks?: string[]
}

export interface TeamSpec {
    slug: string
    members?: string[]
}

export interface LabelSpec {
    name: string
    color?: string
    description?: string
}

/** Rendered CI fragments (from the stack pack) the VCS provider wraps in its own envelope. */
export interface CiPlan {
    /** partial id → rendered YAML/script body. */
    partials: Record<string, string>
    /** Tier-1 path globs the protected-file guard should watch. */
    tier1Paths: string[]
}

export interface VcsProvider extends ProviderMeta {
    kind: 'vcs'
    /** Emit the code-owners file mapping tier paths to approver teams. */
    emitCodeowners(tiers: TierModel, ctx: ProviderContext): VirtualFile
    /** Emit CI workflow files (the envelope) wrapping the pack's CI partials. */
    emitCiWorkflows(plan: CiPlan, ctx: ProviderContext): VirtualFile[]
    /** THE real gate. Configure branch protection server-side. */
    ensureBranchProtection(rules: BranchProtectionRule[], ctx: ProviderContext): Promise<ActionResult[]>
    ensureTeam?(team: TeamSpec, ctx: ProviderContext): Promise<ActionResult>
    ensureLabels(labels: LabelSpec[], ctx: ProviderContext): Promise<ActionResult>
}

export interface PmProvider extends ProviderMeta {
    kind: 'pm'
