import {existsSync} from 'node:fs'
import {readFile, writeFile} from 'node:fs/promises'
import {join} from 'node:path'

export const LOCKFILE_NAME = 'arche.lock.json'

export interface LockedFile {
    hash: string
    owner: string
    merge: string
}

/** The machine source of truth for idempotency and (later) migration. */
export interface ArcheLock {
    version: 1
    arche: string
    generatedAt: string
    files: Record<string, LockedFile>
}

export function emptyLock(archeVersion: string): ArcheLock {
    return {version: 1, arche: archeVersion, generatedAt: new Date().toISOString(), files: {}}
}

export async function readLock(cwd: string): Promise<ArcheLock | undefined> {
    const path = join(cwd, LOCKFILE_NAME)
    if (!existsSync(path)) return undefined
    try {
        const parsed = JSON.parse(await readFile(path, 'utf8')) as ArcheLock
        return parsed.version === 1 ? parsed : undefined
    } catch {
        return undefined
    }
}

export async function writeLock(cwd: string, lock: ArcheLock): Promise<void> {
    await writeFile(join(cwd, LOCKFILE_NAME), `${JSON.stringify(lock, null, 2)}\n`, 'utf8')
}

