import type {RegionMarker} from '@arche/kernel'

export interface RegionMergeResult {
    merged: string
    changed: boolean
}

/**
 * Replace the text between `marker.begin` and `marker.end` with `body`. If the markers are
 * absent, append a fresh managed region to the end of the file. Text outside the markers is
 * never touched — that is what makes it safe to write into a user-owned file.
 */
export function mergeManagedRegion(existing: string, body: string, marker: RegionMarker): RegionMergeResult {
    const lines = existing.split('\n')
    const beginIdx = lines.findIndex((line) => line.trim() === marker.begin.trim())
    const endIdx = lines.findIndex((line) => line.trim() === marker.end.trim())

    if (beginIdx !== -1 && endIdx > beginIdx) {
        const before = lines.slice(0, beginIdx + 1)
        const after = lines.slice(endIdx)
        const merged = [...before, ...body.split('\n'), ...after].join('\n')
        return {merged, changed: merged !== existing}
    }

    const block = `${marker.begin}\n${body}\n${marker.end}`
    if (existing.length === 0) return {merged: `${block}\n`, changed: true}
    const sep = existing.endsWith('\n') ? '' : '\n'
    return {merged: `${existing}${sep}\n${block}\n`, changed: true}
}

/** The full-file contents for a freshly created managed-region file. */
export function wrapRegion(body: string, marker: RegionMarker): string {
    return `${marker.begin}\n${body}\n${marker.end}\n`
}

