import type {EngineInput, ResolvedRuleFragment, ResolvedTemplateEntry, RuleDocPlan, TemplateGraph} from './types'

/**
 * Merge the tech-agnostic base and the selected stack pack into a single render graph.
 *
 * - **Files** are keyed by output path; a later source (the pack) overrides the base on a
 *   collision. Predicated files (`when`) are dropped when the predicate is false.
 * - **Rule fragments** are grouped by their target doc and sorted by `(order, source)` so
 *   composition is fully deterministic — the same inputs always yield byte-identical docs.
 */
export function compose(input: EngineInput): TemplateGraph {
    const {config, base, pack} = input
    const sources = [base, pack]

    const files: ResolvedTemplateEntry[] = []
    for (const source of sources) {
        for (const entry of source.files) {
            if (entry.when && !entry.when(config)) continue
            const resolved: ResolvedTemplateEntry = {templatesDir: source.templatesDir, entry}
            const collision = files.findIndex((f) => f.entry.out === entry.out)
            if (collision >= 0) files[collision] = resolved
            else files.push(resolved)
        }
    }

    const byDoc = new Map<string, ResolvedRuleFragment[]>()
    for (const source of sources) {
        for (const fragment of source.ruleFragments) {
            if (fragment.when && !fragment.when(config)) continue
            const list = byDoc.get(fragment.doc) ?? []
            list.push({templatesDir: source.templatesDir, fragment})
            byDoc.set(fragment.doc, list)
        }
    }

    const ruleDocs: RuleDocPlan[] = [...byDoc.entries()]
        .map(([doc, fragments]) => ({
            doc,
            out: `.claude/rules/${doc}.md`,
            fragments: [...fragments].sort(byOrderThenSource),
        }))
        .sort((a, b) => a.doc.localeCompare(b.doc))

    return {files, ruleDocs, emitted: []}
}

function byOrderThenSource(a: ResolvedRuleFragment, b: ResolvedRuleFragment): number {
    return a.fragment.order - b.fragment.order || a.fragment.source.localeCompare(b.fragment.source)
}

