import {existsSync} from 'node:fs'
import {readFile} from 'node:fs/promises'
import {join} from 'node:path'
import type {VirtualFile} from '@arche/kernel'
import {sha256} from './hash'
import type {ArcheLock} from './lockfile'
import {mergeManagedRegion, wrapRegion} from './mergeRegion'
import type {ChangeKind, ChangePlan, FileChange} from './types'

/**
 * Compute the {@link ChangePlan} by a three-way diff of each rendered file against what is
 * on disk and what the lockfile last recorded. This is where brownfield safety and
 * idempotency live: a re-run of `apply` produces only `unchanged`/`skip` changes, and a
 * user's edits to an Arche-owned file surface as `conflict` rather than being clobbered.
 */
export async function plan(files: VirtualFile[], cwd: string, lock: ArcheLock | undefined): Promise<ChangePlan> {
    const changes: FileChange[] = []
    for (const file of files) {
        const abs = join(cwd, file.path)
        const existing = existsSync(abs) ? await readFile(abs, 'utf8') : undefined
        changes.push(computeChange(file, existing, lock?.files[file.path]?.hash))
    }
