import {chmod, mkdir, writeFile} from 'node:fs/promises'
import {dirname, join} from 'node:path'
import type {ActionResult} from '@arche/kernel'
import {sha256} from './hash'
import {emptyLock, writeLock} from './lockfile'
import type {ApplyResult, ChangeKind, ChangePlan} from './types'

export interface ApplyOptions {
    archeVersion: string
    /** Turn `conflict` changes into overwrites. Default false. */
    force?: boolean
    /** When false, compute the result and lockfile but do not touch disk (dry run). Default true. */
    write?: boolean
}

const WRITE_KINDS: ReadonlySet<ChangeKind> = new Set(['create', 'update', 'update-region'])
const TRACK_KINDS: ReadonlySet<ChangeKind> = new Set(['create', 'update', 'update-region', 'unchanged'])

/**
 * Execute a {@link ChangePlan}: write the files that changed, leave `skip`/`unchanged`
 * alone, and surface `conflict`s (only overwriting them under `force`). Rewrites the
 * lockfile with the hash of every Arche-owned file so the next run is a clean 3-way diff.
 *
 * Provider server-side actions (branch protection, CODEOWNERS teams) are executed by the
 * caller and reported via {@link ApplyResult.providerActions}; this function owns files only.
 */
export async function apply(plan: ChangePlan, opts: ApplyOptions): Promise<ApplyResult> {
    const {archeVersion, force = false, write = true} = opts
    const lock = emptyLock(archeVersion)
    const written: string[] = []
    const skipped: string[] = []
    const conflicts: string[] = []

    for (const change of plan.changes) {
        const isWrite = WRITE_KINDS.has(change.kind) || (change.kind === 'conflict' && force)

        if (change.kind === 'conflict' && !force) conflicts.push(change.path)

        if (isWrite) {
            if (write) {
                const abs = join(plan.cwd, change.path)
                await mkdir(dirname(abs), {recursive: true})
                await writeFile(abs, change.nextContents, 'utf8')
                if (change.executable) await chmod(abs, 0o755)
            }
            written.push(change.path)
        } else if (change.kind === 'skip' || change.kind === 'unchanged') {
            skipped.push(change.path)
        }

        const track = (TRACK_KINDS.has(change.kind) || (change.kind === 'conflict' && force)) && change.owner !== 'user'
        if (track) {
            lock.files[change.path] = {hash: sha256(change.nextContents), owner: change.owner, merge: change.merge}
        }
    }

    if (write) await writeLock(plan.cwd, lock)

    const providerActions: ActionResult[] = []
    return {cwd: plan.cwd, written, skipped, conflicts, providerActions}
}

