import type {VirtualFile} from '@arche/kernel'
import {apply, type ApplyOptions} from './apply'
import {compose} from './compose'
import {readLock} from './lockfile'
import {plan} from './plan'
import {render} from './render'
import type {ApplyResult, ChangePlan, EngineInput, RenderContext} from './types'

const DEFAULT_VERSION = '0.0.0'

/** Build the Eta render context from an {@link EngineInput}. */
export function renderContext(input: EngineInput): RenderContext {
    return {
        config: input.config,
        now: input.now ?? new Date().toISOString(),
        archeVersion: input.archeVersion ?? DEFAULT_VERSION,
    }
}

/** Stage 1–2: compose + render into virtual files (no disk access to the target repo). */
export async function renderProject(input: EngineInput): Promise<VirtualFile[]> {
    return render(compose(input), renderContext(input))
}

/** Stage 1–4: render, then diff against the target repo + lockfile. Pure — no writes. */
export async function planProject(input: EngineInput): Promise<ChangePlan> {
    const files = await renderProject(input)
    const lock = await readLock(input.cwd)
    return plan(files, input.cwd, lock)
}

/** The full pipeline: render → plan → apply. Returns both the plan and the apply result. */
export async function applyProject(
    input: EngineInput,
    opts?: Partial<Omit<ApplyOptions, 'archeVersion'>>,
): Promise<{plan: ChangePlan; result: ApplyResult}> {
    const changePlan = await planProject(input)
    const result = await apply(changePlan, {
        archeVersion: input.archeVersion ?? DEFAULT_VERSION,
        force: opts?.force ?? false,
        write: opts?.write ?? true,
    })
    return {plan: changePlan, result}
}

