import {existsSync} from 'node:fs'
import {mkdtemp, readFile, writeFile} from 'node:fs/promises'
import {tmpdir} from 'node:os'
import {join} from 'node:path'
import {fileURLToPath} from 'node:url'
import {hashRegion} from '@arche/kernel'
import type {StackPack, TemplateSource} from '@arche/pack-sdk'
import {parseConfig} from '@arche/schema'
import {beforeEach, describe, expect, it} from 'vitest'
import {applyProject, planProject, renderProject} from './engine'
import type {EngineInput} from './types'

const fixturesDir = fileURLToPath(new URL('./__fixtures__', import.meta.url))

const base: TemplateSource = {
    id: 'base',
    templatesDir: join(fixturesDir, 'base/templates'),
    files: [
        {template: 'AGENTS.md.eta', out: 'AGENTS.md', owner: 'base', merge: 'replace'},
        {template: 'claude.md.eta', out: 'CLAUDE.md', owner: 'base', merge: 'create-if-absent'},
    ],
    ruleFragments: [{doc: 'conventions', order: 10, template: 'conventions.base.md.eta', source: 'base'}],
}

const pack: StackPack = {
    id: 'node',
    templatesDir: join(fixturesDir, 'pack/templates'),
    files: [
        {template: 'gitignore.eta', out: '.gitignore', owner: 'pack:node', merge: 'create-if-absent'},
        {template: 'region.eta', out: 'config.yml', owner: 'pack:node', merge: 'managed-region', region: hashRegion()},
    ],
    ruleFragments: [{doc: 'conventions', order: 20, template: 'conventions.node.md.eta', source: 'pack:node'}],
}

const config = parseConfig({project: {name: 'acme'}, stackPack: {id: 'node'}})

function makeInput(cwd: string): EngineInput {
    return {config, base, pack, cwd, archeVersion: '1.2.3'}
}

let cwd: string
beforeEach(async () => {
    cwd = await mkdtemp(join(tmpdir(), 'arche-core-'))
})

describe('render', () => {
    it('renders templates with the config context', async () => {
        const files = await renderProject(makeInput(cwd))
        const agents = files.find((f) => f.path === 'AGENTS.md')
        expect(agents?.contents).toContain('acme — AI Development Foundation')
        expect(agents?.contents).toContain('Trunk: main · Integration: develop')
        expect(agents?.contents).toContain('Arche v1.2.3')
    })

    it('composes a rule doc from base + pack fragments in order', async () => {
        const files = await renderProject(makeInput(cwd))
        const doc = files.find((f) => f.path === '.claude/rules/conventions.md')
        expect(doc).toBeDefined()
        const text = doc!.contents
        expect(text).toContain('Cross-cutting conventions for acme')
        expect(text).toContain('TypeScript (node pack)')
        expect(text).toContain('source=base')
        expect(text).toContain('source=pack:node')
        // base (order 10) is composed before the node pack (order 20)
        expect(text.indexOf('Cross-cutting conventions')).toBeLessThan(text.indexOf('TypeScript (node pack)'))
    })
})

describe('apply', () => {
    it('creates all files on a greenfield repo and is idempotent on re-run', async () => {
        const first = await applyProject(makeInput(cwd))
        expect(first.result.written).toContain('AGENTS.md')
        expect(first.result.written).toContain('.claude/rules/conventions.md')
        expect(first.result.conflicts).toHaveLength(0)
        expect(existsSync(join(cwd, 'arche.lock.json'))).toBe(true)

        const second = await planProject(makeInput(cwd))
        const kinds = new Set(second.changes.map((c) => c.kind))
        expect([...kinds].sort()).toEqual(['skip', 'unchanged'])
        expect(second.changes.every((c) => c.kind === 'unchanged' || c.kind === 'skip')).toBe(true)
    })

    it('honors create-if-absent — never touches a file that already exists', async () => {
        await writeFile(join(cwd, '.gitignore'), 'custom-entry\n', 'utf8')
        const {plan} = await applyProject(makeInput(cwd))
        const change = plan.changes.find((c) => c.path === '.gitignore')
        expect(change?.kind).toBe('skip')
        expect(await readFile(join(cwd, '.gitignore'), 'utf8')).toBe('custom-entry\n')
    })

    it('surfaces a conflict for an untracked pre-existing Arche-owned file, without clobbering it', async () => {
        await writeFile(join(cwd, 'AGENTS.md'), 'legacy hand-written content\n', 'utf8')
        const {plan, result} = await applyProject(makeInput(cwd))
        const change = plan.changes.find((c) => c.path === 'AGENTS.md')
        expect(change?.kind).toBe('conflict')
        expect(result.conflicts).toContain('AGENTS.md')
        expect(await readFile(join(cwd, 'AGENTS.md'), 'utf8')).toBe('legacy hand-written content\n')
    })

    it('overwrites a conflict when force is set', async () => {
        await writeFile(join(cwd, 'AGENTS.md'), 'legacy\n', 'utf8')
        const {result} = await applyProject(makeInput(cwd), {force: true})
        expect(result.written).toContain('AGENTS.md')
        expect(await readFile(join(cwd, 'AGENTS.md'), 'utf8')).toContain('acme — AI Development Foundation')
    })

    it('updates only the managed region, preserving surrounding user content', async () => {
        const original = ['top: true', '# >>> arche:managed', 'STALE', '# <<< arche:managed', 'bottom: true', ''].join(
            '\n',
        )
        await writeFile(join(cwd, 'config.yml'), original, 'utf8')
        const {plan} = await applyProject(makeInput(cwd))
        const change = plan.changes.find((c) => c.path === 'config.yml')
        expect(change?.kind).toBe('update-region')
        const result = await readFile(join(cwd, 'config.yml'), 'utf8')
        expect(result).toContain('top: true')
        expect(result).toContain('bottom: true')
        expect(result).toContain('node pack managed block for acme')
        expect(result).not.toContain('STALE')
    })

    it('does not write to disk in dry-run mode', async () => {
        const {result} = await applyProject(makeInput(cwd), {write: false})
        expect(result.written.length).toBeGreaterThan(0)
        expect(existsSync(join(cwd, 'AGENTS.md'))).toBe(false)
        expect(existsSync(join(cwd, 'arche.lock.json'))).toBe(false)
    })
})

