        const {result} = await applyProject(makeInput(cwd), {write: false})
        expect(result.written.length).toBeGreaterThan(0)
        expect(existsSync(join(cwd, 'AGENTS.md'))).toBe(false)
        expect(existsSync(join(cwd, 'arche.lock.json'))).toBe(false)
    })
})

