import type {StackPack, TemplateSource} from '@arche/pack-sdk'
import type {AnyProvider, ProviderPlugin, ProviderSet} from '@arche/provider-sdk'
import type {ArcheConfig} from '@arche/schema'
import {templatesBase} from '@arche/templates-base'

export const ARCHE_VERSION = '0.0.0'

/**
 * Injectable dependencies for the CLI commands. The bin wires the real implementations;
 * tests inject fakes (an empty pack, no providers) so command logic can be exercised
 * without dynamic package resolution.
 */
export interface CliDeps {
    version: string
    base: TemplateSource
    loadPack(id: string, cwd: string): Promise<StackPack>
    loadProviders(config: ArcheConfig, cwd: string): Promise<ProviderSet>
}

/** Dynamically import a stack pack package (`@arche/pack-<id>`). */
async function realLoadPack(id: string): Promise<StackPack> {
    const name = `@arche/pack-${id}`
    try {
        // Dynamic specifier — the module type is not statically known here.
        const mod = (await import(name)) as {default?: StackPack; pack?: StackPack}
        const pack = mod.default ?? mod.pack
        if (!pack) throw new Error(`${name} does not export a stack pack`)
        return pack
    } catch (cause) {
        throw new Error(`Could not load stack pack '${id}' (expected package '${name}'). Is it installed?`, {cause})
    }
}

/** Resolve each configured provider (`@arche/provider-<id>`), degrading gracefully. */
async function realLoadProviders(config: ArcheConfig): Promise<ProviderSet> {
    const set: ProviderSet = {}
    const selections = [config.providers.vcs, config.providers.pm, config.providers.wiki]
    for (const selection of selections) {
        if (selection.id === 'none') continue
        const name = `@arche/provider-${selection.id}`
        try {
            const mod = (await import(name)) as {default?: ProviderPlugin}
            const plugin = mod.default
            if (!plugin) continue
            const provider = plugin.create(config) as AnyProvider
            set[provider.kind] = provider as never
        } catch {
            // Degrade: the provider package is not installed. `arche doctor` will report the gap.
            process.stderr.write(`  ! provider '${selection.id}' not installed — skipping (files still scaffold)\n`)
        }
    }
    return set
}

export function realDeps(): CliDeps {
    return {version: ARCHE_VERSION, base: templatesBase, loadPack: realLoadPack, loadProviders: realLoadProviders}
}

