import type {ChangeKind, ChangePlan} from '@arche/core'

const SYMBOLS: Record<ChangeKind, string> = {
    create: '+',
    update: '~',
    'update-region': '~',
    unchanged: '=',
    skip: '·',
    conflict: '!',
}

/** A one-line-per-file view of a change plan. */
export function formatPlan(plan: ChangePlan): string {
    if (plan.changes.length === 0) return '  (nothing to do)'
    return plan.changes
        .map((c) => {
            const suffix = c.kind === 'conflict' ? `   (conflict: ${c.reason ?? 'differs'})` : ''
            return `  ${SYMBOLS[c.kind]} ${c.path}${suffix}`
        })
        .join('\n')
}

/** A compact `"3 create, 2 unchanged"` summary line. */
export function summarize(plan: ChangePlan): string {
    const counts = new Map<ChangeKind, number>()
    for (const c of plan.changes) counts.set(c.kind, (counts.get(c.kind) ?? 0) + 1)
    return [...counts.entries()].map(([kind, n]) => `${n} ${kind}`).join(', ') || 'no changes'
}

