import * as clack from '@clack/prompts'
import {findConfigPath, type ArcheConfigInput} from '@arche/schema'
import type {CliDeps} from '../deps'
import {runApply} from './apply'

export interface InitAnswers {
    name: string
    packId: string
    vcs: {id: string; org?: string; repo?: string}
    pm: {id: string}
    wiki: {id: string}
}

export interface InitOpts {
    yes?: boolean
    json?: boolean
}

/** Build the config object that `arche init` will persist. */
export function buildConfigObject(a: InitAnswers): ArcheConfigInput {
    const vcs =
        a.vcs.id === 'none'
            ? {id: 'none'}
            : {id: a.vcs.id, ...(a.vcs.org ? {org: a.vcs.org} : {}), ...(a.vcs.repo ? {repo: a.vcs.repo} : {})}
    return {
        project: {name: a.name},
        stackPack: {id: a.packId},
        providers: {vcs, pm: {id: a.pm.id}, wiki: {id: a.wiki.id}},
    }
}

/** Render an `arche.config.ts` from the collected answers. */
export function generateConfigTs(a: InitAnswers): string {
    const body = JSON.stringify(buildConfigObject(a), null, 4)
    return [
        "import {defineConfig} from '@arche/schema'",
        '',
        '/**',
        ' * Arche configuration. Defaults are opinionated and overridable — see @arche/schema.',
        ' * Re-run `arche apply` after changing this file.',
        ' */',
        `export default defineConfig(${body})`,
        '',
    ].join('\n')
}

export async function isGreenfield(cwd: string): Promise<boolean> {
    if (!existsSync(cwd)) return true
    const entries = await readdir(cwd)
    return entries.filter((e) => e !== '.git').length === 0
}

/** Best-effort parse of `git remote get-url origin` into org/repo. */
export function detectVcsRemote(cwd: string): {org?: string; repo?: string} {
    try {
        const url = execFileSync('git', ['remote', 'get-url', 'origin'], {cwd, stdio: ['ignore', 'pipe', 'ignore']})
            .toString()
            .trim()
        const match = url.match(/[/:]([^/]+)\/([^/]+?)(?:\.git)?$/)
        if (match) return {org: match[1], repo: match[2]}
    } catch {
        // no git remote — that's fine
    }
    return {}
}

async function askText(message: string, initial: string): Promise<string> {
    const value = await clack.text({message, defaultValue: initial, placeholder: initial})
    if (clack.isCancel(value)) {
        clack.cancel('Cancelled.')
        process.exit(0)
    }
    return value || initial
}

async function askSelect(message: string, options: Array<{value: string; label: string}>, initial: string): Promise<string> {
    const value = await clack.select({message, options, initialValue: initial})
    if (clack.isCancel(value)) {
        clack.cancel('Cancelled.')
        process.exit(0)
    }
    return value as string
}

