    const existing = findConfigPath(cwd)
    if (existing) {
        process.stdout.write(`arche.config already exists (${existing}) — running apply instead.\n`)
        await runApply(cwd, {write: true}, deps)
        return
    }

    const greenfield = await isGreenfield(cwd)
    const defaults: InitAnswers = {
        name: basename(cwd) || 'my-project',
        packId: 'node',
        vcs: {id: 'github', ...detectVcsRemote(cwd)},
        pm: {id: 'none'},
        wiki: {id: 'none'},
    }

    let answers = defaults
    if (!opts.yes) {
        clack.intro('Arche — AI-development foundation')
        clack.note(greenfield ? 'Greenfield repo detected.' : 'Existing repo — scaffolding non-destructively.')
        const name = await askText('Project name', defaults.name)
        const packId = await askText('Stack pack id', defaults.packId)
        const vcsId = await askSelect(
            'VCS provider',
            [
                {value: 'github', label: 'GitHub'},
                {value: 'gitlab', label: 'GitLab'},
                {value: 'none', label: 'None'},
            ],
            defaults.vcs.id,
        )
        let org: string | undefined
        let repo: string | undefined
        if (vcsId !== 'none') {
            org = await askText('VCS org / owner', defaults.vcs.org ?? '')
            repo = await askText('Repository name', defaults.vcs.repo ?? defaults.name)
        }
        const pmId = await askSelect(
            'Project management',
            [
                {value: 'none', label: 'None'},
                {value: 'jira', label: 'Jira'},
                {value: 'linear', label: 'Linear'},
            ],
            defaults.pm.id,
        )
        const wikiId = await askSelect(
            'Wiki',
            [
                {value: 'none', label: 'None'},
                {value: 'confluence', label: 'Confluence'},
                {value: 'notion', label: 'Notion'},
            ],
            defaults.wiki.id,
        )
        answers = {name, packId, vcs: {id: vcsId, org, repo}, pm: {id: pmId}, wiki: {id: wikiId}}
    }

    const file = opts.json ? 'arche.config.json' : 'arche.config.ts'
    const contents = opts.json
        ? `${JSON.stringify(buildConfigObject(answers), null, 2)}\n`
        : generateConfigTs(answers)
    await writeFile(join(cwd, file), contents, 'utf8')
    if (!opts.yes) clack.outro(`Wrote ${file} — applying the foundation…`)
    await runApply(cwd, {write: true}, deps)
}

