#!/usr/bin/env node
import {resolve} from 'node:path'
import {cac} from 'cac'
import {runApply, runPlan} from './commands/apply'
import {runInit} from './commands/init'
import {realDeps} from './deps'

const deps = realDeps()
const cli = cac('arche')

async function run(fn: () => Promise<unknown>): Promise<void> {
    try {
        await fn()
    } catch (error) {
        process.stderr.write(`\n✖ ${(error as Error).message}\n`)
        process.exitCode = 1
    }
}

cli.command('init [dir]', 'Scaffold the Arche AI-development foundation')
    .option('--yes', 'Accept defaults, skip prompts')
    .option('--json', 'Write arche.config.json instead of .ts')
    .action((dir: string | undefined, options: {yes?: boolean; json?: boolean}) =>
        run(() => runInit(resolve(dir ?? '.'), {yes: options.yes, json: options.json}, deps)),
    )

cli.command('apply [dir]', 'Reconcile the repository with arche.config')
    .option('--force', 'Overwrite conflicting files')
    .action((dir: string | undefined, options: {force?: boolean}) =>
        run(() => runApply(resolve(dir ?? '.'), {force: options.force, write: true}, deps)),
    )

cli.command('plan [dir]', 'Show the change plan without writing (dry run)').action((dir: string | undefined) =>
    run(() => runPlan(resolve(dir ?? '.'), deps)),
)

cli.help()
cli.version(deps.version)
cli.parse()

export {runApply, runInit, runPlan}

