import {existsSync} from 'node:fs'
import {mkdtemp, readFile, writeFile} from 'node:fs/promises'
import {tmpdir} from 'node:os'
import {join} from 'node:path'
import type {StackPack} from '@arche/pack-sdk'
import {templatesBase} from '@arche/templates-base'
import {beforeEach, describe, expect, it} from 'vitest'
import type {CliDeps} from '../deps'
import {runApply, runPlan} from './apply'

const emptyPack: StackPack = {id: 'empty', templatesDir: '/unused', files: [], ruleFragments: []}

const deps: CliDeps = {
    version: '0.0.0',
    base: templatesBase,
    loadPack: async () => emptyPack,
    loadProviders: async () => ({}),
}

let cwd: string
beforeEach(async () => {
    cwd = await mkdtemp(join(tmpdir(), 'arche-cli-'))
    await writeFile(join(cwd, 'arche.config.json'), JSON.stringify({project: {name: 'Sandbox'}, stackPack: {id: 'node'}}), 'utf8')
})

describe('runApply', () => {
    it('scaffolds the base foundation into a greenfield repo', async () => {
        const result = await runApply(cwd, {write: true}, deps)
        expect(result.written).toContain('AGENTS.md')
        expect(result.written).toContain('CLAUDE.md')
        expect(result.written).toContain('.claude/rules/tiers.md')
        expect(result.written).toContain('.claude/skills/session-start/SKILL.md')
        expect(result.conflicts).toHaveLength(0)
        expect(existsSync(join(cwd, 'arche.lock.json'))).toBe(true)
    })

    it('is idempotent — a second run makes no changes', async () => {
        await runApply(cwd, {write: true}, deps)
        const plan = await runPlan(cwd, deps)
        expect(plan.changes.every((c) => c.kind === 'unchanged' || c.kind === 'skip')).toBe(true)
    })

    it('surfaces a conflict for a pre-existing AGENTS.md and leaves it untouched', async () => {
        await writeFile(join(cwd, 'AGENTS.md'), 'legacy\n', 'utf8')
        const result = await runApply(cwd, {write: true}, deps)
        expect(result.conflicts).toContain('AGENTS.md')
        expect(await readFile(join(cwd, 'AGENTS.md'), 'utf8')).toBe('legacy\n')
    })
})

