import {readFile} from 'node:fs/promises'
import {join} from 'node:path'
import {Eta} from 'eta'
import type {VirtualFile} from '@arche/kernel'
import type {RenderContext, TemplateGraph} from './types'

/**
 * Render a {@link TemplateGraph} into {@link VirtualFile}s. Templates are `.eta` files that
 * receive the {@link RenderContext} as `it`. Auto-escaping is off — Arche renders Markdown,
 * YAML, and source, not HTML, so we never want quotes/angle-brackets escaped.
 */
export async function render(graph: TemplateGraph, ctx: RenderContext): Promise<VirtualFile[]> {
    const eta = new Eta({autoEscape: false, autoTrim: false, useWith: false})
    const out: VirtualFile[] = []

    for (const {templatesDir, entry} of graph.files) {
        const template = await readFile(join(templatesDir, entry.template), 'utf8')
        const contents = eta.renderString(template, ctx)
        out.push({
            path: entry.out,
            contents,
            owner: entry.owner ?? 'base',
            merge: entry.merge ?? 'replace',
            ...(entry.region ? {region: entry.region} : {}),
            ...(entry.executable ? {executable: true} : {}),
        })
    }

    for (const doc of graph.ruleDocs) {
        const parts: string[] = [ruleDocHeader(doc.doc)]
        for (const {templatesDir, fragment} of doc.fragments) {
            const template = await readFile(join(templatesDir, fragment.template), 'utf8')
            const body = eta.renderString(template, ctx).trim()
            parts.push(`<!-- arche:fragment source=${fragment.source} order=${fragment.order} -->\n${body}`)
        }
        out.push({path: doc.out, contents: `${parts.join('\n\n')}\n`, owner: 'arche', merge: 'replace'})
    }

    out.push(...graph.emitted)
    return out
}

function ruleDocHeader(doc: string): string {
    return [
        '<!-- arche:generated — do not edit by hand.',
        '     Composed from rule fragments in your stack pack / templates-base.',
        '     Edit the fragment templates, then re-run `arche apply`. -->',
        '',
        `# ${toTitle(doc)}`,
    ].join('\n')
}

function toTitle(slug: string): string {
    return slug
        .split(/[-_]/)
        .map((word) => (word ? word.charAt(0).toUpperCase() + word.slice(1) : word))
        .join(' ')
}

