import {promisify} from 'node:util'

const run = promisify(execFile)

/** A thin, injectable wrapper over the `gh` CLI so the provider is testable without network. */
export interface GhClient {
    authed(): Promise<boolean>
    api(method: string, path: string, fields?: Record<string, string | number | boolean>): Promise<{ok: boolean; detail?: string}>
}

export const realGh: GhClient = {
    async authed() {
        try {
            await run('gh', ['auth', 'status'])
            return true
        } catch {
            return false
        }
    },
    async api(method, path, fields = {}) {
        const args = ['api', '-X', method, path]
        for (const [key, value] of Object.entries(fields)) args.push('-f', `${key}=${String(value)}`)
        try {
            await run('gh', args)
            return {ok: true}
        } catch (error) {
            return {ok: false, detail: (error as Error).message}
        }
    },
}

