import type {TierModel} from '@arche/schema'

/**
 * Build a GitHub CODEOWNERS file from the tier model. This — together with branch
 * protection's "require review from Code Owners" — is the *authoritative* Tier 1/2 gate.
 * The CI guard is only advisory.
 */
export function buildCodeowners(tiers: TierModel): string {
    const lines = [
        '# CODEOWNERS — generated by Arche. Do not edit by hand.',
        '# The authoritative Tier 1/2 review gate: pair this with branch protection',
        "# (\"Require review from Code Owners\") for it to actually block merges.",
        '',
    ]

    const t1 = tiers.tier1
    if (t1.paths.length > 0 && t1.owners.length > 0) {
        lines.push(`# Tier 1 — ${t1.label}`)
        for (const path of t1.paths) lines.push(`${toPattern(path)} ${t1.owners.join(' ')}`)
        lines.push('')
    }

    const t2 = tiers.tier2
    const t2Owners = t2.owners.length > 0 ? t2.owners : t1.owners
    if (t2.paths.length > 0 && t2Owners.length > 0) {
        lines.push(`# Tier 2 — ${t2.label}`)
        for (const path of t2.paths) lines.push(`${toPattern(path)} ${t2Owners.join(' ')}`)
        lines.push('')
    }

    return lines.join('\n')
}

/** CODEOWNERS uses gitignore-style patterns; normalise a `**` glob to a subtree prefix. */
function toPattern(glob: string): string {
    return glob.replace(/\/\*\*\/\*$/, '/').replace(/\/\*\*$/, '/')
}

