import {existsSync} from 'node:fs'
import {join} from 'node:path'
import {LOCKFILE_NAME} from '@arche/core'
import {loadConfig} from '@arche/schema'
import type {CliDeps} from '../deps'

/**
 * `arche doctor` — answer the question "is the *real* gate actually on?". It deliberately
 * distinguishes the advisory emitted files (CODEOWNERS, CI guard) from the authoritative
 * server-side branch protection, which files alone cannot prove.
 */
export async function runDoctor(cwd: string, deps: CliDeps): Promise<void> {
    const {config} = await loadConfig(cwd)
    const providers = await deps.loadProviders(config, cwd)
    const lines: string[] = [`\nArche doctor · ${cwd}`]
    const mark = (ok: boolean, label: string) => lines.push(`  ${ok ? '✓' : '✗'} ${label}`)

