import {execFile} from 'node:child_process'
import {existsSync} from 'node:fs'
import {join} from 'node:path'
import {promisify} from 'node:util'
import type {ArcheConfig} from '@arche/schema'

const run = promisify(execFile)

/**
 * Point git at the scaffolded `.githooks/` directory so the commit-msg / pre-commit hooks
 * actually run. No-op when git hooks are disabled, the repo isn't a git repo, or `.githooks`
 * wasn't scaffolded. Transparent and reversible (`git config --unset core.hooksPath`).
 */
export async function maybeInstallGitHooks(cwd: string, config: ArcheConfig): Promise<string | undefined> {
    if (!config.primitives.gitHooks) return undefined
    if (!existsSync(join(cwd, '.git')) || !existsSync(join(cwd, '.githooks'))) return undefined
    try {
        await run('git', ['config', 'core.hooksPath', '.githooks'], {cwd})
        return 'git hooks activated (core.hooksPath=.githooks)'
    } catch {
        return undefined
    }
}

