import {loadConfig} from '@arche/schema'
import type {CliDeps} from '../deps'
import {formatPlan, summarize} from '../output'
import {buildProviderFiles, runServerSideGates} from '../providerFiles'

export interface ApplyOpts {
    force?: boolean
    write?: boolean
}

async function buildInput(cwd: string, deps: CliDeps): Promise<EngineInput> {
    const {config} = await loadConfig(cwd)
    const pack = await deps.loadPack(config.stackPack.id, cwd)
    const providers = await deps.loadProviders(config, cwd)
    const extraFiles = await buildProviderFiles(config, pack, providers, cwd, deps.version)
    return {config, base: deps.base, pack, cwd, providers, extraFiles, archeVersion: deps.version}
}

/** `arche plan` — render + diff, no writes. */
export async function runPlan(cwd: string, deps: CliDeps): Promise<ChangePlan> {
    const plan = await planProject(await buildInput(cwd, deps))
    process.stdout.write(`\nArche plan · ${cwd}\n${formatPlan(plan)}\n\n${summarize(plan)}\n`)
    return plan
}

/** `arche apply` — reconcile the working tree, then run the authoritative server-side gates. */
export async function runApply(cwd: string, opts: ApplyOpts, deps: CliDeps): Promise<ApplyResult> {
    const input = await buildInput(cwd, deps)
    const {plan, result} = await applyProject(input, {force: opts.force ?? false, write: opts.write ?? true})
    process.stdout.write(`\nArche apply · ${cwd}\n${formatPlan(plan)}\n\n`)

    if (opts.write !== false) {
        const actions = await runServerSideGates(input.config, input.providers ?? {}, cwd)
        result.providerActions.push(...actions)
        printActions(actions)
    }

    if (result.conflicts.length > 0) {
        const list = result.conflicts.map((p) => `  - ${p}`).join('\n')
        process.stdout.write(`⚠ ${result.conflicts.length} conflict(s) left untouched. Resolve them, or re-run with --force:\n${list}\n\n`)
    }
    process.stdout.write(`✓ ${result.written.length} written · ${result.skipped.length} unchanged/skipped\n`)
    return result
}

function printActions(actions: ActionResult[]): void {
    if (actions.length === 0) return
    process.stdout.write('Server-side gates (the real Tier 1 enforcement):\n')
    for (const action of actions) {
        process.stdout.write(`  ${statusSymbol(action.status)} ${action.action} — ${action.status}${action.detail ? ` (${action.detail})` : ''}\n`)
        for (const step of action.manualSteps ?? []) process.stdout.write(`      ${step}\n`)
    }
    process.stdout.write('\n')
}

