import type {VirtualFile} from '@arche/kernel'
import type {ArcheConfig} from '@arche/schema'

/**
 * Propagate the single rule source (`.claude/rules/*` + `AGENTS.md`) to the other AI tools
 * a team uses, so there is one place to edit and everything else is derived. Each mirror
 * carries a `synced-from` header so it is obviously generated. Gated by
 * `primitives.multiAiPropagation`.
 */
export function propagateAiRules(files: VirtualFile[], config: ArcheConfig): VirtualFile[] {
    const targets = config.primitives.multiAiPropagation
    if (!targets || targets.length === 0) return []

    const ruleDocs = files
        .filter((f) => f.path.startsWith('.claude/rules/') && f.path.endsWith('.md'))
        .sort((a, b) => a.path.localeCompare(b.path))
    const agents = files.find((f) => f.path === 'AGENTS.md')
    const out: VirtualFile[] = []

    if (targets.includes('copilot')) {
        const parts = [synced('AGENTS.md + .claude/rules/'), '', '# Copilot instructions', '']
        if (agents) parts.push(agents.contents)
        for (const doc of ruleDocs) parts.push(doc.contents)
        out.push({path: '.github/copilot-instructions.md', contents: `${parts.join('\n')}\n`, owner: 'arche', merge: 'replace'})
    }

    if (targets.includes('cursor')) {
        for (const doc of ruleDocs) {
            const name = doc.path.slice('.claude/rules/'.length).replace(/\.md$/, '')
            const mdc = [
                '---',
                `description: ${name} conventions (synced by Arche)`,
                'alwaysApply: true',
                '---',
                synced(doc.path),
                '',
                doc.contents,
            ].join('\n')
            out.push({path: `.cursor/rules/${name}.mdc`, contents: `${mdc}\n`, owner: 'arche', merge: 'replace'})
        }
    }

    if (targets.includes('windsurf')) {
        const parts = [synced('AGENTS.md + .claude/rules/'), '']
        if (agents) parts.push(agents.contents)
        for (const doc of ruleDocs) parts.push(doc.contents)
        out.push({path: '.windsurfrules', contents: `${parts.join('\n')}\n`, owner: 'arche', merge: 'replace'})
    }

    return out
}

function synced(source: string): string {
    return `<!-- synced-from: ${source} — generated by Arche. Do not edit; edit the source rule fragments and re-run \`arche apply\`. -->`
}

