import {existsSync} from 'node:fs'
import {join} from 'node:path'
import {fileURLToPath} from 'node:url'
import {definePack, type StackPack} from '@arche/pack-sdk'

/**
 * The generic TypeScript/Node stack pack — the first and reference pack. It contributes
 * ESM/TS conventions and Vitest testing rules on top of the tech-agnostic base, a
 * `new-module` scaffold skill, an `.editorconfig`, and a change-scoped-test CI partial
 * that the VCS provider embeds into its workflow envelope.
 */
const templatesDir = fileURLToPath(new URL('../templates', import.meta.url))

/** Brownfield auto-detection confidence (0..1) that a repo is a Node/TS project. */
async function detect(cwd: string): Promise<number> {
    let score = 0
    if (existsSync(join(cwd, 'package.json'))) score += 0.6
    if (existsSync(join(cwd, 'tsconfig.json')) || existsSync(join(cwd, 'tsconfig.base.json'))) score += 0.3
    if (existsSync(join(cwd, 'pnpm-workspace.yaml'))) score += 0.1
    return Math.min(score, 1)
}

export const packNode: StackPack = definePack({
    id: 'node',
    templatesDir,
    detect,
    files: [
        {template: 'editorconfig.eta', out: '.editorconfig', owner: 'pack:node', merge: 'create-if-absent'},
        {
            template: 'skills/new-module.SKILL.md.eta',
            out: '.claude/skills/new-module/SKILL.md',
            owner: 'pack:node',
            merge: 'replace',
        },
        {
            template: 'semgrep.yml.eta',
            out: 'semgrep.yml',
            owner: 'pack:node',
            merge: 'replace',
            when: (config) => config.primitives.staticAnalysis.semgrep,
        },
    ],
    ruleFragments: [
        {doc: 'conventions', order: 20, template: 'rules/conventions.node.md.eta', source: 'pack:node'},
        {doc: 'testing', order: 20, template: 'rules/testing.node.md.eta', source: 'pack:node'},
    ],
    ciPartials: {
        // Consumed by the VCS provider's emitCiWorkflows() to build the test job body.
        changeScopedTests: {
            template: 'ci/change-scoped-tests.partial.yml.eta',
            out: '',
            owner: 'pack:node',
            merge: 'replace',
        },
    },
})

export default packNode

