import type {VirtualFile} from '@arche/kernel'
import type {RegistryEntry, StackPack} from '@arche/pack-sdk'
import type {ArcheConfig} from '@arche/schema'

/**
 * Run the stack pack's registry scanners and render each into an agent-readable Markdown
 * table under `.claude/registry/`, so Claude reads a table instead of grepping the tree.
 */
export async function buildRegistryFiles(config: ArcheConfig, pack: StackPack, cwd: string): Promise<VirtualFile[]> {
    if (!config.primitives.registry || !pack.registryScanners?.length) return []
    const files: VirtualFile[] = []
    for (const scanner of pack.registryScanners) {
        const entries = await scanner.scan(cwd)
        files.push({
            path: `.claude/registry/${scanner.id}.md`,
            contents: formatRegistry(scanner.id, entries),
            owner: 'arche',
            merge: 'replace',
        })
    }
    return files
}

function formatRegistry(id: string, entries: RegistryEntry[]): string {
    const header = `<!-- arche:generated registry (${id}). Regenerated by \`arche apply\` / \`arche sync\`. -->\n\n# Registry — ${id}\n\n`
    if (entries.length === 0) return `${header}_No entries found._\n`
    const rows = entries.map((e) => `| \`${e.name}\` | ${e.kind} | \`${e.path}\` |`).join('\n')
    return `${header}| Name | Kind | Path |\n| --- | --- | --- |\n${rows}\n`
}

