import {planProject} from '@arche/core'
import type {CliDeps} from '../deps'
import {buildEngineInput, runApply} from './apply'

/** Files derived from the single rule source — what `sync` regenerates / drift-checks. */
function isDerived(path: string): boolean {
    return (
        path.startsWith('.cursor/') ||
        path === '.github/copilot-instructions.md' ||
        path === '.windsurfrules' ||
        path.startsWith('.claude/rules/') ||
        path.startsWith('.claude/registry/')
    )
}

/** `arche sync` — regenerate derived AI-tool files; `--check` fails on drift (for CI). */
export async function runSync(cwd: string, opts: {check?: boolean}, deps: CliDeps): Promise<void> {
    if (!opts.check) {
        await runApply(cwd, {write: true}, deps)
        return
    }
    const plan = await planProject(await buildEngineInput(cwd, deps))
    const drift = plan.changes.filter((c) => isDerived(c.path) && c.kind !== 'unchanged' && c.kind !== 'skip')
    if (drift.length === 0) {
        process.stdout.write('✓ Derived AI-tool files are in sync.\n')
        return
    }
    process.stdout.write('✗ Derived files are out of sync — run `arche sync`:\n')
    for (const c of drift) process.stdout.write(`  ${c.kind} ${c.path}\n`)
    process.exitCode = 1
}

