    .option('--force', 'Overwrite conflicting files')
    .action((dir: string | undefined, options: {force?: boolean}) =>
        run(() => runApply(resolve(dir ?? '.'), {force: options.force, write: true}, deps)),
    )

cli.command('plan [dir]', 'Show the change plan without writing (dry run)').action((dir: string | undefined) =>
    run(() => runPlan(resolve(dir ?? '.'), deps)),
)

