import type {VirtualFile} from '@arche/kernel'
import {parseConfig} from '@arche/schema'
import {describe, expect, it} from 'vitest'
import {propagateAiRules} from './propagate'

const files: VirtualFile[] = [
    {path: 'AGENTS.md', contents: '# Policy\nBranch rules here.', owner: 'base', merge: 'replace'},
    {path: '.claude/rules/conventions.md', contents: '# Conventions\nDo X.', owner: 'arche', merge: 'replace'},
]

describe('propagateAiRules', () => {
    it('emits Cursor + Copilot mirrors with synced-from provenance by default', () => {
        const out = propagateAiRules(files, parseConfig({project: {name: 'X'}, stackPack: {id: 'node'}}))
        const paths = out.map((f) => f.path)
        expect(paths).toContain('.github/copilot-instructions.md')
        expect(paths).toContain('.cursor/rules/conventions.mdc')
        const mdc = out.find((f) => f.path === '.cursor/rules/conventions.mdc')?.contents ?? ''
        expect(mdc).toContain('synced-from')
        expect(mdc).toContain('Do X.')
        const copilot = out.find((f) => f.path === '.github/copilot-instructions.md')?.contents ?? ''
        expect(copilot).toContain('Branch rules here.')
        expect(copilot).toContain('Do X.')
    })

    it('emits nothing when propagation is disabled', () => {
        const out = propagateAiRules(
            files,
            parseConfig({project: {name: 'X'}, stackPack: {id: 'node'}, primitives: {multiAiPropagation: []}}),
        )
        expect(out).toHaveLength(0)
    })
})

