import {mkdir, mkdtemp, writeFile} from 'node:fs/promises'
import {tmpdir} from 'node:os'
import {join} from 'node:path'
import {describe, expect, it} from 'vitest'
import {moduleScanner} from './scanner'

describe('moduleScanner', () => {
    it('lists .ts modules and ignores tests, decls, and node_modules', async () => {
        const dir = await mkdtemp(join(tmpdir(), 'arche-scan-'))
        await mkdir(join(dir, 'src'), {recursive: true})
        await mkdir(join(dir, 'node_modules/x'), {recursive: true})
        await writeFile(join(dir, 'src/foo.ts'), 'export const foo = 1')
        await writeFile(join(dir, 'src/foo.test.ts'), 'test')
        await writeFile(join(dir, 'src/types.d.ts'), 'declare const x: number')
        await writeFile(join(dir, 'node_modules/x/y.ts'), 'export const y = 1')

        const entries = await moduleScanner.scan(dir)
        const names = entries.map((e) => e.name)
        expect(names).toContain('foo')
        expect(names).not.toContain('foo.test')
        expect(names).not.toContain('types')
        expect(entries.every((e) => !e.path.includes('node_modules'))).toBe(true)
    })
})

