#!/usr/bin/env node
/**
 * Arche full audit — the repeatable "what's the status of Arche" check.
 *
 * Runs static verification (typecheck, tests, build) and a black-box e2e smoke against the
 * built CLI (init → idempotent plan → doctor). Prints a status report and exits non-zero on
 * any failure. Run after every phase: `node scripts/audit.mjs`.
 */
import {execSync} from 'node:child_process'
import {existsSync, mkdtempSync, readdirSync, rmSync} from 'node:fs'
import {tmpdir} from 'node:os'
import {join} from 'node:path'

const root = process.cwd()
const cli = join(root, 'packages/cli/dist/index.js')
const results = []

function record(ok, name, detail) {
    results.push({ok, name, detail})
}
function step(name, fn) {
    try {
        fn()
        record(true, name)
    } catch (error) {
        record(false, name, String(error.message ?? error).split('\n')[0])
    }
}
function sh(cmd, opts = {}) {
    return execSync(cmd, {cwd: root, stdio: 'pipe', ...opts}).toString()
}

// ── Static verification ───────────────────────────────────────────────
step('typecheck (tsc --noEmit)', () => sh('pnpm typecheck'))
step('unit + integration tests (vitest)', () => {
    const out = sh('pnpm test')
    const m = out.match(/Tests\s+(\d+)\s+passed/)
    if (m) results.push({ok: true, name: `  → ${m[1]} tests passing`, meta: true})
})
step('build all packages (tsup)', () => sh('pnpm build'))

// ── Black-box e2e against the built CLI ───────────────────────────────
let sandbox
step('e2e: `arche init` scaffolds a repo', () => {
    if (!existsSync(cli)) throw new Error('CLI not built')
    sandbox = mkdtempSync(join(tmpdir(), 'arche-audit-'))
    sh(`node ${cli} init ${sandbox} --yes --json`)
    const expected = [
        'AGENTS.md',
        'CLAUDE.md',
        '.claude/settings.json',
        '.claude/rules/tiers.md',
        '.claude/skills/session-start/SKILL.md',
        '.docs/memory/projectState.md',
        '.githooks/pre-commit',
        '.githooks/commit-msg',
        'coderabbit.yaml',
        'semgrep.yml',
        'arche.lock.json',
    ]
    const missing = expected.filter((f) => !existsSync(join(sandbox, f)))
    if (missing.length) throw new Error(`missing scaffolded files: ${missing.join(', ')}`)
})
step('e2e: re-apply is idempotent', () => {
    const out = sh(`node ${cli} plan ${sandbox}`)
    if (/^\s{2}[+~!]\s/m.test(out)) throw new Error('plan shows create/update/conflict on re-run')
})
step('e2e: `arche doctor` runs', () => sh(`node ${cli} doctor ${sandbox}`))
if (sandbox) rmSync(sandbox, {recursive: true, force: true})

// ── Report ────────────────────────────────────────────────────────────
const count = (dir) => (existsSync(join(root, dir)) ? readdirSync(join(root, dir)).length : 0)
const failed = results.filter((r) => !r.ok).length

process.stdout.write('\n── Arche audit ─────────────────────────────\n')
for (const r of results) {
    if (r.meta) {
        process.stdout.write(`    ${r.name}\n`)
        continue
    }
    process.stdout.write(`  ${r.ok ? '✓' : '✗'} ${r.name}${r.detail ? ` — ${r.detail}` : ''}\n`)
}
process.stdout.write(
    `\n  packages: ${count('packages')} · providers: ${count('providers')} · packs: ${count('packs')}\n`,
)
process.stdout.write(`  ${results.filter((r) => r.ok && !r.meta).length}/${results.filter((r) => !r.meta).length} checks passed\n`)
process.stdout.write('────────────────────────────────────────────\n')
process.exit(failed > 0 ? 1 : 0)

