import {readdir} from 'node:fs/promises'
import {join, relative} from 'node:path'
import type {RegistryEntry, RegistryScanner} from '@arche/pack-sdk'

const IGNORED_DIRS = new Set(['node_modules', 'dist', 'coverage', '.git'])
const MAX_ENTRIES = 500
const MAX_DEPTH = 8

/** Walk the repo listing TypeScript modules (excluding tests, decls, node_modules, dist). */
async function scanModules(cwd: string): Promise<RegistryEntry[]> {
    const out: RegistryEntry[] = []

    async function walk(dir: string, depth: number): Promise<void> {
        if (depth > MAX_DEPTH || out.length >= MAX_ENTRIES) return
        let entries: Awaited<ReturnType<typeof readdir>>
        try {
            entries = await readdir(dir, {withFileTypes: true})
        } catch {
            return
        }
        for (const entry of entries) {
            if (out.length >= MAX_ENTRIES) return
            const full = join(dir, entry.name)
            if (entry.isDirectory()) {
                if (!IGNORED_DIRS.has(entry.name) && !entry.name.startsWith('.')) await walk(full, depth + 1)
            } else if (
                entry.isFile() &&
                entry.name.endsWith('.ts') &&
                !entry.name.endsWith('.test.ts') &&
                !entry.name.endsWith('.d.ts')
            ) {
                out.push({kind: 'module', name: entry.name.replace(/\.ts$/, ''), path: relative(cwd, full)})
            }
        }
    }

    await walk(cwd, 0)
    return out.sort((a, b) => a.path.localeCompare(b.path))
}

export const moduleScanner: RegistryScanner = {id: 'modules', scan: scanModules}

