import type {Capability} from '@arche/kernel'
import type {PmProvider, ProviderPlugin} from '@arche/provider-sdk'
import type {ArcheConfig} from '@arche/schema'

/**
 * The Jira PM provider. It knows how to recognise a story key (e.g. `STORE-123`) inside a
 * branch name, commit, or PR reference, and how that key threads through the workflow —
 * the spine that ties requirements ↔ stories ↔ branches ↔ commits ↔ E2E specs.
 */
export function createJiraProvider(config: ArcheConfig): PmProvider {
    const pm = config.providers.pm
    const keys = pm.projectKeys ?? []
    const raw = pm.storyKeyPattern ?? config.requirementSpine.storyKeyPattern
    // Build a *search* regex (anchors stripped) so keys can be found inside a longer string.
    const source = keys.length > 0 ? `\\b(?:${keys.join('|')})-\\d+\\b` : raw.replace(/^\^/, '').replace(/\$$/, '')
    const pattern = new RegExp(source)

    return {
        id: 'jira',
        kind: 'pm',
        capabilities: new Set<Capability>(['story-linking']),
        parseStoryKey(ref: string): string | null {
            return ref.match(pattern)?.[0] ?? null
        },
        linkCommitConvention() {
            return {branchPrefixPattern: `${config.branchModel.feature.replace('*', '')}<KEY>-`}
        },
    }
}

const plugin: ProviderPlugin = {id: 'jira', kind: 'pm', create: createJiraProvider}
export default plugin

