import {parseConfig} from '@arche/schema'
import {describe, expect, it} from 'vitest'
import {createJiraProvider} from './index'

describe('jira provider', () => {
    it('extracts a story key from a branch name using projectKeys', () => {
        const config = parseConfig({
            project: {name: 'X'},
            stackPack: {id: 'node'},
            providers: {pm: {id: 'jira', projectKeys: ['STORE', 'PLAT']}},
        })
        const jira = createJiraProvider(config)
        expect(jira.parseStoryKey('feature/STORE-123-add-cart')).toBe('STORE-123')
        expect(jira.parseStoryKey('PLAT-9: fix build')).toBe('PLAT-9')
        expect(jira.parseStoryKey('chore/no-key-here')).toBeNull()
    })

    it('falls back to the requirement-spine pattern when no projectKeys are set', () => {
        const config = parseConfig({project: {name: 'X'}, stackPack: {id: 'node'}, providers: {pm: {id: 'jira'}}})
        const jira = createJiraProvider(config)
        expect(jira.parseStoryKey('feature/ABC-42-thing')).toBe('ABC-42')
    })

    it('describes the branch-prefix convention for the spine', () => {
        const config = parseConfig({project: {name: 'X'}, stackPack: {id: 'node'}, providers: {pm: {id: 'jira'}}})
        expect(createJiraProvider(config).linkCommitConvention().branchPrefixPattern).toBe('feature/<KEY>-')
    })
})

