import type {FileOwner, MergePolicy, RegionMarker} from '@arche/kernel'
import type {ArcheConfig} from '@arche/schema'

/**
 * The stack-pack contract. A pack is the *only* place tech-stack-specific knowledge lives:
 * conventions, component/test scaffolds, lint/test tooling, CI test-selection, and
 * registry scanners. The engine composes a pack on top of the tech-agnostic base
 * ({@link TemplateSource}) without either knowing about the other.
 */

/** A predicate over the resolved config — used to conditionally include a file or fragment. */
export type ConfigPredicate = (config: ArcheConfig) => boolean

/** A reference to an `.eta` template that renders into one output file. */
export interface TemplateEntry {
    /** Path to the `.eta` template, relative to the source's `templatesDir`. */
    template: string
    /** Repo-relative output path (POSIX). */
    out: string
    /** Defaults to the source's own owner (`base` or `pack:<id>`). */
    owner?: FileOwner
    /** Defaults to `replace`. */
    merge?: MergePolicy
    region?: RegionMarker
    executable?: boolean
    /** Include this file only when the predicate returns true. */
    when?: ConfigPredicate
}

/**
 * A section-scoped chunk of a rule document. Fragments targeting the same `doc` are
 * composed (sorted by `order`, then `source`) into `.claude/rules/<doc>.md`. This is how
 * core-rules and pack-rules combine without file-level conflicts.
 */
export interface RuleFragment {
    /** Target rule doc id (renders to `.claude/rules/<doc>.md`). */
    doc: string
    /** Sort key within the doc. */
    order: number
    /** Path to the `.eta` fragment template, relative to `templatesDir`. */
    template: string
    /** Provenance, e.g. `'base'` or `'pack:node'`. */
    source: string
    when?: ConfigPredicate
}

/** A named scaffold (component/page/test) that powers the pack's `new-*` skills. */
export interface ScaffoldDef {
    /** Directory of `.eta` files for this scaffold, relative to `templatesDir`. */
    dir: string
    description?: string
}

export interface RegistryEntry {
    kind: string
    name: string
    path: string
    [key: string]: unknown
}

/** Populates the agent-readable codebase registry (`.claude/registry/*`). */
export interface RegistryScanner {
    id: string
    scan(cwd: string): Promise<RegistryEntry[]>
}

/** Common base for both the tech-agnostic base layer and every stack pack. */
export interface TemplateSource {
    id: string
    /** Absolute path to this source's templates directory. */
    templatesDir: string
    files: TemplateEntry[]
    ruleFragments: RuleFragment[]
}

export interface StackPack extends TemplateSource {
    /** Brownfield auto-detection confidence for this stack, 0..1. */
    detect?: (cwd: string) => Promise<number>
    scaffolds?: Record<string, ScaffoldDef>
    registryScanners?: RegistryScanner[]
    /** CI fragments the VCS provider embeds into its workflow envelope. */
    ciPartials?: Record<string, TemplateEntry>
}

/** Identity helper for authoring a stack pack with full type checking. */
export function definePack(pack: StackPack): StackPack {
    return pack
}

/** Identity helper for authoring the base template source. */
export function defineTemplateSource(source: TemplateSource): TemplateSource {
    return source
}

