import {buildCodeowners} from './codeowners'
import {realGh, type GhClient} from './gh'
import {buildProtectedFileGuard, buildQualityWorkflow} from './workflows'

const CAPABILITIES: Capability[] = ['codeowners', 'ci', 'branch-protection', 'teams', 'labels']

/**
 * The GitHub VCS provider. `emit*` methods return files the engine writes (advisory); the
 * `ensure*` methods perform the authoritative server-side actions via `gh`, degrading to
 * printed manual steps when unauthenticated. The `gh` client is injectable for testing.
 */
export function createGitHubProvider(config: ArcheConfig, gh: GhClient = realGh): VcsProvider {
    const {org, repo} = config.providers.vcs
    const slug = org && repo ? `${org}/${repo}` : undefined

    return {
        id: 'github',
        kind: 'vcs',
        capabilities: new Set(CAPABILITIES),

        emitCodeowners(tiers: TierModel): VirtualFile {
            return {path: '.github/CODEOWNERS', contents: buildCodeowners(tiers), owner: 'provider:github', merge: 'replace'}
        },

        emitCiWorkflows(plan: CiPlan, ctx: ProviderContext): VirtualFile[] {
            const testSteps = plan.partials.changeScopedTests ?? '      - run: echo "no test partial provided"'
            const branches = {trunk: ctx.config.branchModel.trunk, integration: ctx.config.branchModel.integration}
            return [
                {
                    path: '.github/workflows/arche-quality.yml',
                    contents: buildQualityWorkflow(testSteps, branches),
                    owner: 'provider:github',
                    merge: 'replace',
                },
                {
                    path: '.github/workflows/arche-protected-files.yml',
                    contents: buildProtectedFileGuard(plan.tier1Paths, ctx.config.tiers.tier1.owners),
                    owner: 'provider:github',
                    merge: 'replace',
                },
            ]
        },

        async ensureBranchProtection(rules: BranchProtectionRule[]): Promise<ActionResult[]> {
            if (!slug) return rules.map((r) => notConfigured('ensureBranchProtection', r.branch))
            if (!(await gh.authed())) {
                return rules.map((r) => unauth('ensureBranchProtection', r.branch, manualBranchProtection(slug, r)))
            }
            const results: ActionResult[] = []
            for (const rule of rules) {
                const res = await gh.api('PUT', `repos/${slug}/branches/${rule.branch}/protection`, protectionFields(rule))
                results.push(
                    res.ok
                        ? {action: `ensureBranchProtection(${rule.branch})`, status: 'applied'}
                        : {action: `ensureBranchProtection(${rule.branch})`, status: 'failed', detail: res.detail},
                )
            }
            return results
        },

        async ensureTeam(team: TeamSpec): Promise<ActionResult> {
            if (!org) return notConfigured('ensureTeam', team.slug)
            if (!(await gh.authed())) {
                return unauth('ensureTeam', team.slug, [`gh api -X POST orgs/${org}/teams -f name='${team.slug}'`])
            }
            const res = await gh.api('POST', `orgs/${org}/teams`, {name: team.slug})
            return res.ok
                ? {action: `ensureTeam(${team.slug})`, status: 'applied'}
                : {action: `ensureTeam(${team.slug})`, status: 'failed', detail: res.detail}
        },

        async ensureLabels(labels: LabelSpec[]): Promise<ActionResult> {
            if (!slug) return notConfigured('ensureLabels', 'labels')
            if (!(await gh.authed())) {
                return unauth(
                    'ensureLabels',
                    'labels',
                    labels.map((l) => `gh label create '${l.name}' -R ${slug}`),
                )
            }
            for (const label of labels) await gh.api('POST', `repos/${slug}/labels`, {name: label.name, color: label.color ?? 'ededed'})
            return {action: 'ensureLabels', status: 'applied', detail: `${labels.length} label(s)`}
        },
    }
}

function notConfigured(action: string, subject: string): ActionResult {
    return {action: `${action}(${subject})`, status: 'skipped', detail: 'no org/repo configured in arche.config'}
}

function unauth(action: string, subject: string, manualSteps: string[]): ActionResult {
    return {action: `${action}(${subject})`, status: 'unauthenticated', manualSteps}
}

function protectionFields(rule: BranchProtectionRule): Record<string, string | number | boolean> {
    return {
        'required_pull_request_reviews[require_code_owner_reviews]': rule.requireCodeOwnerReview,
        'required_pull_request_reviews[required_approving_review_count]': rule.requiredApprovals,
        enforce_admins: true,
    }
}

function manualBranchProtection(slug: string, rule: BranchProtectionRule): string[] {
    return [
        `# Enable branch protection with code-owner review on '${rule.branch}':`,
        `gh api -X PUT repos/${slug}/branches/${rule.branch}/protection \\`,
        `  -f 'required_pull_request_reviews[require_code_owner_reviews]=true' \\`,
        `  -f 'required_pull_request_reviews[required_approving_review_count]=${rule.requiredApprovals}' \\`,
        `  -f 'enforce_admins=true'`,
    ]
}

const plugin: ProviderPlugin = {id: 'github', kind: 'vcs', create: (config) => createGitHubProvider(config)}
export default plugin

export {buildCodeowners} from './codeowners'
export {buildProtectedFileGuard, buildQualityWorkflow} from './workflows'
export type {GhClient} from './gh'

