import {renderTemplate, type RenderContext} from '@arche/core'
import type {ActionResult, VirtualFile} from '@arche/kernel'
import type {StackPack} from '@arche/pack-sdk'
import type {BranchProtectionRule, ProviderContext, ProviderSet} from '@arche/provider-sdk'
import type {ArcheConfig} from '@arche/schema'

/**
 * Ask the configured VCS provider for the files it owns (CODEOWNERS + CI workflows),
 * gated by the enabled primitives and the provider's declared capabilities. Returns them
 * as {@link VirtualFile}s for the engine to write through the normal plan/apply path.
 */
export async function buildProviderFiles(
    config: ArcheConfig,
    pack: StackPack,
    providers: ProviderSet,
    cwd: string,
    version: string,
): Promise<VirtualFile[]> {
    const vcs = providers.vcs
    if (!vcs) return []
    const ctx: ProviderContext = {config, cwd}
    const files: VirtualFile[] = []

    if (config.primitives.codeowners && vcs.capabilities.has('codeowners')) {
        files.push(vcs.emitCodeowners(config.tiers, ctx))
    }

    if (config.primitives.ciWorkflows && vcs.capabilities.has('ci')) {
        const rctx: RenderContext = {config, now: new Date().toISOString(), archeVersion: version}
        const partials: Record<string, string> = {}
        for (const [name, entry] of Object.entries(pack.ciPartials ?? {})) {
            partials[name] = await renderTemplate(pack.templatesDir, entry.template, rctx)
        }
        files.push(...vcs.emitCiWorkflows({partials, tier1Paths: config.tiers.tier1.paths}, ctx))
    }

    return files
}

/**
 * Run the *authoritative* server-side gates (branch protection with code-owner review).
 * This is the real Tier 1 enforcement — the emitted CI guard is only advisory.
 */
export async function runServerSideGates(config: ArcheConfig, providers: ProviderSet, cwd: string): Promise<ActionResult[]> {
    const vcs = providers.vcs
    if (!vcs || !config.primitives.branchProtection || !vcs.capabilities.has('branch-protection')) return []
    const rules: BranchProtectionRule[] = [config.branchModel.trunk, config.branchModel.integration].map((branch) => ({
        branch,
        requireCodeOwnerReview: true,
        requiredApprovals: 1,
    }))
    return vcs.ensureBranchProtection(rules, {config, cwd})
}

