import type {BranchProtectionRule, ProviderContext} from '@arche/provider-sdk'
import {parseConfig} from '@arche/schema'
import {describe, expect, it, vi} from 'vitest'
import type {GhClient} from './gh'
import {createGitHubProvider} from './index'

const config = parseConfig({
    project: {name: 'X'},
    stackPack: {id: 'node'},
    providers: {vcs: {id: 'github', org: 'Acme', repo: 'store'}},
    tiers: {
        tier1: {owners: ['@acme/leads'], paths: ['AGENTS.md', 'packages/schema/**']},
        tier2: {owners: ['@acme/devs'], paths: ['packages/core/**']},
    },
})

const ctx: ProviderContext = {config, cwd: '/tmp/x'}
const rules: BranchProtectionRule[] = [{branch: 'main', requireCodeOwnerReview: true, requiredApprovals: 1}]

const authedGh: GhClient = {authed: async () => true, api: async () => ({ok: true})}
const unauthedGh: GhClient = {authed: async () => false, api: async () => ({ok: false})}

describe('emitCodeowners', () => {
    it('maps tier paths to owner teams', () => {
        const file = createGitHubProvider(config, authedGh).emitCodeowners(config.tiers, ctx)
        expect(file.path).toBe('.github/CODEOWNERS')
        expect(file.owner).toBe('provider:github')
        expect(file.contents).toContain('AGENTS.md @acme/leads')
        expect(file.contents).toContain('packages/schema/ @acme/leads')
        expect(file.contents).toContain('packages/core/ @acme/devs')
    })
})

describe('emitCiWorkflows', () => {
    it('wraps the pack CI partial and emits an advisory tier-1 guard', () => {
        const files = createGitHubProvider(config, authedGh).emitCiWorkflows(
            {partials: {changeScopedTests: '      - run: pnpm test'}, tier1Paths: ['packages/schema/**']},
            ctx,
        )
        const quality = files.find((f) => f.path === '.github/workflows/arche-quality.yml')?.contents ?? ''
        const guard = files.find((f) => f.path === '.github/workflows/arche-protected-files.yml')?.contents ?? ''
        expect(quality).toContain('- run: pnpm test')
        expect(quality).toContain('branches: [develop, main]')
        expect(guard).toContain('^packages/schema/.*')
        expect(guard).toContain('ADVISORY')
    })
})

describe('ensureBranchProtection (the real gate)', () => {
    it('degrades to manual steps when gh is not authenticated', async () => {
        const results = await createGitHubProvider(config, unauthedGh).ensureBranchProtection(rules, ctx)
        expect(results[0]?.status).toBe('unauthenticated')
        expect(results[0]?.manualSteps?.join('\n')).toContain('repos/Acme/store/branches/main/protection')
    })

    it('applies protection via gh when authenticated', async () => {
        const api = vi.fn(async () => ({ok: true}))
        const gh: GhClient = {authed: async () => true, api}
        const results = await createGitHubProvider(config, gh).ensureBranchProtection(rules, ctx)
        expect(results[0]?.status).toBe('applied')
        expect(api).toHaveBeenCalledWith('PUT', 'repos/Acme/store/branches/main/protection', expect.any(Object))
    })

    it('skips when no org/repo is configured', async () => {
        const bare = parseConfig({project: {name: 'X'}, stackPack: {id: 'node'}, providers: {vcs: {id: 'github'}}})
        const results = await createGitHubProvider(bare, authedGh).ensureBranchProtection(rules, ctx)
        expect(results[0]?.status).toBe('skipped')
    })
})

