import type {ActionResult, Capability, CiSpec, VirtualFile} from '@arche/kernel'
import type {
    BranchProtectionRule,
    CiPlan,
    LabelSpec,
    ProviderContext,
    ProviderPlugin,
    TierModel,
    VcsProvider,
} from '@arche/provider-sdk'
import type {ArcheConfig} from '@arche/schema'

/**
 * The GitLab VCS provider. It emits the *same* CODEOWNERS content as the GitHub provider
 * (only the path differs) and renders the pack's neutral {@link CiSpec} into a
 * `.gitlab-ci.yml` — so a project can swap `vcs: github → gitlab` with zero pack changes.
 * Server-side protection degrades to manual `glab` steps (no live mutation here).
 */
export function createGitLabProvider(config: ArcheConfig): VcsProvider {
    const {org, repo} = config.providers.vcs
    const project = org && repo ? `${org}/${repo}` : undefined

    return {
        id: 'gitlab',
        kind: 'vcs',
        capabilities: new Set<Capability>(['codeowners', 'ci', 'branch-protection']),

        emitCodeowners(tiers: TierModel): VirtualFile {
            return {path: '.gitlab/CODEOWNERS', contents: buildCodeowners(tiers), owner: 'provider:gitlab', merge: 'replace'}
        },

        emitCiWorkflows(plan: CiPlan, ctx: ProviderContext): VirtualFile[] {
            return [
                {
                    path: '.gitlab-ci.yml',
                    contents: buildGitlabCi(plan.ci, plan.tier1Paths, ctx.config.tiers.tier1.owners),
                    owner: 'provider:gitlab',
                    merge: 'replace',
                },
            ]
        },

        async ensureBranchProtection(rules: BranchProtectionRule[]): Promise<ActionResult[]> {
            return rules.map((rule) => {
                if (!project) {
                    return {action: `ensureBranchProtection(${rule.branch})`, status: 'skipped', detail: 'no group/project configured'}
                }
                return {
                    action: `ensureBranchProtection(${rule.branch})`,
                    status: 'unauthenticated',
                    manualSteps: [
                        `# Protect '${rule.branch}' with code-owner approval on GitLab:`,
                        `glab api -X POST "projects/${encodeURIComponent(project)}/protected_branches" \\`,
                        `  -f name='${rule.branch}' -f code_owner_approval_required=true`,
                    ],
                }
            })
        },

        async ensureLabels(labels: LabelSpec[]): Promise<ActionResult> {
            if (!project) return {action: 'ensureLabels', status: 'skipped', detail: 'no group/project configured'}
            return {
                action: 'ensureLabels',
                status: 'unauthenticated',
                manualSteps: labels.map(
                    (l) => `glab api -X POST "projects/${encodeURIComponent(project)}/labels" -f name='${l.name}' -f color='#${l.color ?? 'ededed'}'`,
                ),
            }
        },
    }
}

function buildCodeowners(tiers: TierModel): string {
    const lines = ['# CODEOWNERS — generated by Arche. Do not edit by hand.', '']
    const t1 = tiers.tier1
    if (t1.paths.length > 0 && t1.owners.length > 0) {
        lines.push(`# Tier 1 — ${t1.label}`)
        for (const path of t1.paths) lines.push(`${toPattern(path)} ${t1.owners.join(' ')}`)
        lines.push('')
    }
    const t2 = tiers.tier2
    const t2Owners = t2.owners.length > 0 ? t2.owners : t1.owners
    if (t2.paths.length > 0 && t2Owners.length > 0) {
        lines.push(`# Tier 2 — ${t2.label}`)
        for (const path of t2.paths) lines.push(`${toPattern(path)} ${t2Owners.join(' ')}`)
        lines.push('')
    }
    return lines.join('\n')
}

function buildGitlabCi(ci: CiSpec | undefined, tier1Paths: string[], owners: string[]): string {
    const image = ci?.runtime === 'node' ? `node:${ci?.runtimeVersion ?? '20'}` : 'debian:stable-slim'
    const before = ci?.runtime === 'node' ? ['corepack enable'] : []
    const script = [...(ci?.install ? [ci.install] : []), ...(ci?.commands ?? ['echo "no commands"'])]
    const regex = tier1Paths.map(globToRegex).join('|') || '$^'
    const approver = owners.join(', ') || 'a code owner'
    const beforeBlock = before.length > 0 ? `  before_script:\n${before.map((s) => `    - ${s}`).join('\n')}\n` : ''

    return `# Generated by Arche — do not edit by hand.
stages:
  - verify
arche-quality:
  stage: verify
  image: ${image}
  rules:
    - if: '$CI_PIPELINE_SOURCE == "merge_request_event"'
${beforeBlock}  script:
${script.map((s) => `    - ${s}`).join('\n')}
# ADVISORY Tier 1 guard — the real gate is CODEOWNERS + protected branches.
arche-protected-files:
  stage: verify
  image: alpine:latest
  rules:
    - if: '$CI_PIPELINE_SOURCE == "merge_request_event"'
  script:
    - apk add --no-cache git >/dev/null
    - CHANGED=$(git diff --name-only "origin/$CI_MERGE_REQUEST_TARGET_BRANCH_NAME"...HEAD || true)
    - echo "$CHANGED" | grep -E '${regex}' && echo "Tier 1 changed — require ${approver} approval" || true
`
}

function toPattern(glob: string): string {
    return glob.replace(/\/\*\*\/\*$/, '/').replace(/\/\*\*$/, '/')
}

function globToRegex(glob: string): string {
    const escaped = glob.replace(/[.+^${}()|[\]\\]/g, '\\$&')
    const body = escaped.replace(/\*\*/g, '.*').replace(/(?<!\.)\*/g, '[^/]*')
    return `^${body}`
}

const plugin: ProviderPlugin = {id: 'gitlab', kind: 'vcs', create: createGitLabProvider}
export default plugin

