import type {BranchProtectionRule, ProviderContext} from '@arche/provider-sdk'
import {parseConfig} from '@arche/schema'
import {describe, expect, it} from 'vitest'
import {createGitLabProvider} from './index'

const config = parseConfig({
    project: {name: 'X'},
    stackPack: {id: 'node'},
    providers: {vcs: {id: 'gitlab', org: 'grp', repo: 'proj'}},
    tiers: {tier1: {owners: ['@grp/leads'], paths: ['AGENTS.md', 'packages/schema/**']}},
})
const ctx: ProviderContext = {config, cwd: '/tmp/x'}
const rules: BranchProtectionRule[] = [{branch: 'main', requireCodeOwnerReview: true, requiredApprovals: 1}]

describe('gitlab provider', () => {
    it('emits CODEOWNERS at the GitLab path with the same owner mappings', () => {
        const file = createGitLabProvider(config).emitCodeowners(config.tiers, ctx)
        expect(file.path).toBe('.gitlab/CODEOWNERS')
        expect(file.contents).toContain('AGENTS.md @grp/leads')
        expect(file.contents).toContain('packages/schema/ @grp/leads')
    })

    it('renders the neutral CiSpec into .gitlab-ci.yml (zero pack changes)', () => {
        const files = createGitLabProvider(config).emitCiWorkflows(
            {ci: {runtime: 'node', runtimeVersion: '20', install: 'pnpm install', commands: ['pnpm typecheck', 'pnpm test']}, tier1Paths: ['packages/schema/**']},
            ctx,
        )
        const ci = files.find((f) => f.path === '.gitlab-ci.yml')?.contents ?? ''
        expect(ci).toContain('image: node:20')
        expect(ci).toContain('- pnpm install')
        expect(ci).toContain('- pnpm test')
        expect(ci).toContain('^packages/schema/.*')
    })

    it('degrades branch protection to manual glab steps', async () => {
        const results = await createGitLabProvider(config).ensureBranchProtection(rules, ctx)
        expect(results[0]?.status).toBe('unauthenticated')
        expect(results[0]?.manualSteps?.join('\n')).toContain('protected_branches')
    })
})

