import {createHash} from 'node:crypto'

export interface RawChunk {
    index: number
    heading: string
    content: string
}

/** Split a Markdown page into chunks by `## H2` section (the required template fields). */
export function chunkByH2(body: string): RawChunk[] {
    const chunks: RawChunk[] = []
    let current: {heading: string; lines: string[]} | null = null
    let index = 0

    for (const line of body.split('\n')) {
        const heading = /^##\s+(.+)$/.exec(line.trim())
        if (heading) {
            if (current) chunks.push({index: index++, heading: current.heading, content: current.lines.join('\n').trim()})
            current = {heading: (heading[1] ?? '').trim(), lines: []}
        } else if (current) {
            current.lines.push(line)
        }
    }
    if (current) chunks.push({index: index++, heading: current.heading, content: current.lines.join('\n').trim()})

    return chunks.filter((c) => c.content.length > 0)
}

/** MD5 checksum used to skip unchanged chunks on re-ingestion. */
export function checksum(content: string): string {
    return createHash('md5').update(content, 'utf8').digest('hex')
}

import {cosineSimilarity} from './similarity'
import type {ConflictFlag, KnowledgeChunk} from './types'

export const DEFAULT_CONFLICT_THRESHOLD = 0.92

export interface ConflictOptions {
    threshold?: number
}

/**
 * Flag chunks from *different pages* that are highly similar (same topic) yet have divergent
 * content — a likely contradiction. Conflicts are surfaced for human triage, never
 * auto-resolved (only a human with engagement context can judge current-vs-target state).
 */
export function detectConflicts(
    target: KnowledgeChunk,
    existing: readonly KnowledgeChunk[],
    opts: ConflictOptions = {},
): ConflictFlag[] {
    const threshold = opts.threshold ?? DEFAULT_CONFLICT_THRESHOLD
    const flags: ConflictFlag[] = []
    for (const other of existing) {
        if (other.pageId === target.pageId) continue
        const similarity = cosineSimilarity(target.embedding, other.embedding)
        if (similarity >= threshold && isDivergent(target.content, other.content)) {
            flags.push({
                chunkAId: target.id,
                chunkBId: other.id,
                similarity,
                summary: `High similarity (${similarity.toFixed(2)}) between "${target.pageTitle}" and "${other.pageTitle}" but divergent content — needs human review.`,
            })
        }
    }
    return flags
}

function isDivergent(a: string, b: string): boolean {
    return a.trim() !== b.trim()
}

