import type {VectorStore} from './ports'
import {cosineSimilarity} from './similarity'
import type {KnowledgeChunk, ScoredChunk} from './types'

/** An in-memory vector store for local dev and tests (no Postgres required). */
export class InMemoryVectorStore implements VectorStore {
    private readonly chunks = new Map<string, KnowledgeChunk>()

    async upsert(chunks: KnowledgeChunk[]): Promise<void> {
        for (const chunk of chunks) this.chunks.set(chunk.id, chunk)
    }

    async query(embedding: number[], topK: number, pageType?: string): Promise<ScoredChunk[]> {
        return [...this.chunks.values()]
            .filter((c) => !pageType || c.pageType === pageType)
            .map((chunk) => ({chunk, similarity: cosineSimilarity(embedding, chunk.embedding)}))
            .sort((a, b) => b.similarity - a.similarity)
            .slice(0, topK)
    }

    async all(): Promise<KnowledgeChunk[]> {
        return [...this.chunks.values()]
    }
}

import type {Embedder, VectorStore} from './ports'
import type {ScoredChunk} from './types'

export interface RagQueryOptions {
    topK?: number
    pageType?: string
}

export interface RagService {
    query(question: string, opts?: RagQueryOptions): Promise<ScoredChunk[]>
}

/** Embed a question and return the most semantically similar stored chunks. */
export function createRagService(embedder: Embedder, store: VectorStore): RagService {
    return {
        async query(question, opts = {}) {
            const [vector] = await embedder.embed([question])
            if (!vector) return []
            return store.query(vector, opts.topK ?? 5, opts.pageType)
        },
    }
}

