                    reason: `missing required field(s): ${REQUIRED_FIELDS.join(', ')}`,
                }
            }

            const embeddings = await deps.embedder.embed(raw.map((c) => c.content))
            const chunks: KnowledgeChunk[] = raw.map((c, i) => ({
                id: `${page.id}#${c.index}`,
                pageId: page.id,
                pageTitle: page.title,
                pageType: page.type,
                spaceKey: page.spaceKey,
                chunkIndex: c.index,
                content: c.content,
                embedding: embeddings[i] ?? [],
                sourceUrl: page.url,
                checksum: checksum(c.content),
            }))

            const existing = await deps.store.all()
            const conflicts = chunks.flatMap((chunk) => detectConflicts(chunk, existing, {threshold: deps.conflictThreshold}))
            await deps.store.upsert(chunks)
            return {pageId: page.id, status: 'success', chunksWritten: chunks.length, conflicts}
        },
    }
}

