import type {Embedder} from './ports'

export interface OpenAiEmbedderOptions {
    apiKey: string
    model?: string
    baseUrl?: string
}

/** Embeddings via the OpenAI REST API (default `text-embedding-3-small`, 1536 dims). */
export function createOpenAiEmbedder(opts: OpenAiEmbedderOptions): Embedder {
    const model = opts.model ?? 'text-embedding-3-small'
    const url = `${opts.baseUrl ?? 'https://api.openai.com/v1'}/embeddings`
    return {
        async embed(texts) {
            if (texts.length === 0) return []
            const res = await fetch(url, {
                method: 'POST',
                headers: {'content-type': 'application/json', authorization: `Bearer ${opts.apiKey}`},
                body: JSON.stringify({model, input: texts}),
            })
            if (!res.ok) throw new Error(`OpenAI embeddings failed: ${res.status} ${await res.text()}`)
            const json = (await res.json()) as {data: Array<{embedding: number[]}>}
            return json.data.map((d) => d.embedding)
        },
    }
}

