import {describe, expect, it} from 'vitest'
import {chunkByH2} from './chunker'
import {detectConflicts} from './conflict'
import {createIngestor} from './ingest'
import {InMemoryVectorStore} from './memory'
import {createKnowledgeHandler, KNOWLEDGE_TOOL} from './mcp'
import type {Embedder} from './ports'
import {createRagService} from './rag'
import {cosineSimilarity} from './similarity'
import type {KnowledgeChunk, RequirementSourceSpec, WikiPage} from './types'

const fakeEmbedder = (fn: (text: string) => number[]): Embedder => ({embed: async (texts) => texts.map(fn)})

const chunk = (id: string, pageId: string, content: string, embedding: number[]): KnowledgeChunk => ({
    id,
    pageId,
    pageTitle: pageId,
    pageType: 'regional-rule',
    spaceKey: 'S',
    chunkIndex: 0,
    content,
    embedding,
    checksum: '',
})

describe('cosineSimilarity', () => {
    it('is 1 for identical, 0 for orthogonal, 0 for mismatched lengths', () => {
        expect(cosineSimilarity([1, 0], [1, 0])).toBeCloseTo(1)
        expect(cosineSimilarity([1, 0], [0, 1])).toBeCloseTo(0)
        expect(cosineSimilarity([1, 2], [1])).toBe(0)
    })
})

describe('chunkByH2', () => {
    it('splits by H2, keeping H3+ content within its section', () => {
        const chunks = chunkByH2('# Title\n## Summary\nHello\n### sub\nmore\n## Owner\nJane')
        expect(chunks.map((c) => c.heading)).toEqual(['Summary', 'Owner'])
        expect(chunks[0]?.content).toContain('Hello')
        expect(chunks[0]?.content).toContain('more')
    })
})

describe('detectConflicts', () => {
    it('flags highly-similar chunks from different pages with divergent content', () => {
        const target = chunk('a', 'pageA', 'EU checkout is SFCC-owned', [1, 0, 0])
        const existing = [chunk('b', 'pageB', 'EU checkout uses Global-e', [0.99, 0.01, 0])]
        expect(detectConflicts(target, existing, {threshold: 0.9})).toHaveLength(1)
    })

    it('does not flag same-page or identical content', () => {
        const target = chunk('a', 'pageA', 'same', [1, 0, 0])
        expect(detectConflicts(target, [chunk('b', 'pageA', 'x', [1, 0, 0])])).toHaveLength(0)
        expect(detectConflicts(target, [chunk('c', 'pageC', 'same', [1, 0, 0])], {threshold: 0.9})).toHaveLength(0)
    })
})

describe('createRagService', () => {
    it('ranks stored chunks by similarity to the query embedding', async () => {
        const store = new InMemoryVectorStore()
        await store.upsert([chunk('1', 'p1', 'cats', [1, 0]), chunk('2', 'p2', 'dogs', [0, 1])])
        const rag = createRagService(fakeEmbedder(() => [1, 0]), store)
        const results = await rag.query('anything')
        expect(results[0]?.chunk.id).toBe('1')
    })
})

describe('createIngestor', () => {
    const source: RequirementSourceSpec = {
        pageTypeLabels: ['architecture-decision'],
        templateFields: ['Summary', 'Decision / Rule / Outcome'],
    }
    const embedder = fakeEmbedder((t) => [t.length, 1])
    const goodPage: WikiPage = {
        id: 'P1',
        title: 'Decision',
        type: 'architecture-decision',
        spaceKey: 'S',
        body: '## Summary\nA thing.\n## Decision / Rule / Outcome\nWe chose X.',
    }

    it('ingests a well-formed page into the store', async () => {
        const store = new InMemoryVectorStore()
        const res = await createIngestor({embedder, store, source}).ingest(goodPage)
        expect(res.status).toBe('success')
        expect(res.chunksWritten).toBe(2)
        expect((await store.all()).length).toBe(2)
    })

    it('skips a page with an unrecognised label', async () => {
        const res = await createIngestor({embedder, store: new InMemoryVectorStore(), source}).ingest({
            ...goodPage,
            type: 'random',
        })
        expect(res.status).toBe('skipped')
    })

    it('marks a page missing required fields as malformed', async () => {
        const res = await createIngestor({embedder, store: new InMemoryVectorStore(), source}).ingest({
            ...goodPage,
            body: '## Summary\nonly a summary',
        })
        expect(res.status).toBe('malformed')
    })
})

describe('knowledge MCP tool', () => {
    it('exposes query_knowledge with a required question input', () => {
        expect(KNOWLEDGE_TOOL.name).toBe('query_knowledge')
        expect(KNOWLEDGE_TOOL.inputSchema.required).toContain('question')
    })

    it('handler returns MCP-shaped results', async () => {
        const store = new InMemoryVectorStore()
        await store.upsert([chunk('1', 'p', 'the answer body', [1, 0])])
        const handler = createKnowledgeHandler(createRagService(fakeEmbedder(() => [1, 0]), store))
        const out = await handler({question: 'q'})
        expect(out.results[0]?.content).toBe('the answer body')
        expect(out.results[0]?.similarity).toBeCloseTo(1)
    })
})

