import {existsSync, readFileSync} from 'node:fs'
import {join} from 'node:path'
import {fileURLToPath} from 'node:url'
import {definePack, type StackPack} from '@arche/pack-sdk'

/**
 * The Salesforce PWA Kit (SFCC) stack pack — the second, deliberately complex pack, proving
 * the ecosystem generalizes beyond the reference `pack-node`. It layers SFCC conventions
 * (TS-only overrides, `commerce-sdk-react`, Chakra tokens, three-layer testing) on top of
 * the tech-agnostic base, and describes an npm-based CI. It mirrors the conventions the
 * reference Zimmermann engagement hand-maintained.
 */
const templatesDir = fileURLToPath(new URL('../templates', import.meta.url))

async function detect(cwd: string): Promise<number> {
    let score = 0
    if (existsSync(join(cwd, 'overrides'))) score += 0.5
    try {
        const pkg = JSON.parse(readFileSync(join(cwd, 'package.json'), 'utf8')) as {
            dependencies?: Record<string, string>
            devDependencies?: Record<string, string>
        }
        const deps = {...pkg.dependencies, ...pkg.devDependencies}
        if (deps['@salesforce/retail-react-app'] || deps['@salesforce/pwa-kit-react-sdk']) score += 0.5
    } catch {
        // no package.json
    }
    return Math.min(score, 1)
}

export const packSfcc: StackPack = definePack({
    id: 'sfcc',
    templatesDir,
    detect,
    files: [],
    ruleFragments: [
        {doc: 'conventions', order: 20, template: 'rules/conventions.sfcc.md.eta', source: 'pack:sfcc'},
        {doc: 'testing', order: 20, template: 'rules/testing.sfcc.md.eta', source: 'pack:sfcc'},
        {doc: 'css', order: 20, template: 'rules/css.sfcc.md.eta', source: 'pack:sfcc'},
    ],
    ci: {
        runtime: 'node',
        runtimeVersion: '20',
        install: 'npm ci',
        commands: ['npm run lint', 'npx tsc --noEmit', 'npm test'],
    },
})

export default packSfcc

