    project: {name: 'Zimmermann'},
    stackPack: {id: 'sfcc'},
    tiers: {
        tier1: {
            owners: ['@ZimmermannAU/tier-1-approvers'],
            paths: ['overrides/app/theme/foundation/**', 'config/**', '.github/workflows/**', 'AGENTS.md'],
        },
        tier2: {
            owners: ['@ZimmermannAU/tier-2-approvers'],
            paths: ['overrides/app/components/product-tile/**', 'overrides/app/components/header/**'],
        },
        tier3: {
            squads: {
                squadA: {paths: ['overrides/app/pages/checkout/**'], owners: ['@ZimmermannAU/pwa-squad-a']},
                squadB: {paths: ['overrides/app/pages/account/**'], owners: ['@ZimmermannAU/pwa-squad-b']},
            },
        },
    },
})

const render = () => renderProject({config, base: templatesBase, pack: packSfcc, cwd: '/tmp/x', archeVersion: '0'})

describe('pack-sfcc', () => {
    it('layers SFCC conventions on top of the base', async () => {
        const files = await render()
        const conv = files.find((f) => f.path === '.claude/rules/conventions.md')?.contents ?? ''
        expect(conv).toContain('Apply DRY, KISS') // base
        expect(conv).toContain('TypeScript only inside `overrides/`') // sfcc
        expect(files.find((f) => f.path === '.claude/rules/css.md')?.contents ?? '').toContain('Chakra props first')
    })

    it('describes an npm-based CI (proving CI intent is stack-specific, not github-specific)', () => {
        expect(packSfcc.ci?.install).toBe('npm ci')
        expect(packSfcc.ci?.commands).toContain('npx tsc --noEmit')
    })

    it('fidelity: reproduces the Zimmermann tier shape from config alone', async () => {
        const tiers = (await render()).find((f) => f.path === '.claude/rules/tiers.md')?.contents ?? ''
        expect(tiers).toContain('overrides/app/theme/foundation/')
        expect(tiers).toContain('@ZimmermannAU/tier-1-approvers')
        expect(tiers).toContain('squadA')
        expect(tiers).toContain('@ZimmermannAU/pwa-squad-a')
    })

    it('detects an SFCC repo (overrides/ + salesforce dep)', async () => {
        const dir = await mkdtemp(join(tmpdir(), 'arche-sfcc-'))
        await mkdir(join(dir, 'overrides'), {recursive: true})
        await writeFile(join(dir, 'package.json'), JSON.stringify({dependencies: {'@salesforce/retail-react-app': '^10'}}))
        expect(await packSfcc.detect?.(dir)).toBeGreaterThan(0.9)
    })
})

