import {existsSync} from 'node:fs'
import {join} from 'node:path'
import {LOCKFILE_NAME, readLock} from '@arche/core'
import type {CliDeps} from '../deps'
import {runApply} from './apply'

/** A version-gated migration that runs when a repo's recorded Arche version predates it. */
export interface Codemod {
    version: string
    name: string
    apply(cwd: string): Promise<string | undefined>
}

/**
 * Registered codemods, applied in order when the repo's recorded version is older than the
 * codemod's version. Empty while Arche is pre-1.0 — the mechanism exists so that a future
 * rename/restructure ships as a codemod rather than a silent overwrite.
 */
export const CODEMODS: Codemod[] = []

/** Compare two `x.y.z` versions; true when `a` is strictly newer than `b`. */
export function isNewer(a: string, b: string): boolean {
    const pa = a.split('.').map((n) => Number(n) || 0)
    const pb = b.split('.').map((n) => Number(n) || 0)
    for (let i = 0; i < 3; i++) {
        const x = pa[i] ?? 0
        const y = pb[i] ?? 0
        if (x !== y) return x > y
    }
    return false
}

/** `arche migrate` — run version-gated codemods, then reconcile with the latest templates. */
export async function runMigrate(cwd: string, deps: CliDeps): Promise<void> {
    if (!existsSync(join(cwd, LOCKFILE_NAME))) {
        process.stdout.write('No arche.lock.json found — run `arche apply` first.\n')
        return
    }
    const lock = await readLock(cwd)
    const from = lock?.arche ?? '0.0.0'
    process.stdout.write(`\nArche migrate · ${cwd}\n  recorded version: ${from} → current: ${deps.version}\n`)

    const pending = CODEMODS.filter((c) => isNewer(c.version, from))
    for (const mod of pending) {
        const detail = await mod.apply(cwd)
        process.stdout.write(`  ✓ codemod ${mod.version} — ${mod.name}${detail ? ` (${detail})` : ''}\n`)
    }
    if (pending.length === 0) process.stdout.write('  no codemods to run.\n')

    process.stdout.write('  reconciling with the latest templates…\n')
    await runApply(cwd, {write: true}, deps)
}

