import {renderProject} from '@arche/core'
import type {StackPack} from '@arche/pack-sdk'
import {parseConfig} from '@arche/schema'
import {describe, expect, it} from 'vitest'
import {templatesBase} from './index'

/** An empty pack so we exercise only the base layer. */
const emptyPack: StackPack = {id: 'test-empty', templatesDir: templatesBase.templatesDir, files: [], ruleFragments: []}

const config = parseConfig({
    project: {name: 'Acme Store', description: 'A test storefront.'},
    stackPack: {id: 'node'},
    tiers: {
        tier1: {owners: ['@acme/leads'], paths: ['config/**', 'AGENTS.md']},
        tier3: {squads: {frontend: {paths: ['src/ui/**'], owners: ['@acme/fe']}}},
    },
})

function render() {
    return renderProject({config, base: templatesBase, pack: emptyPack, cwd: '/tmp/arche-x', archeVersion: '0.1.0'})
}

describe('templates-base', () => {
    it('renders the full base governance layer with no template errors', async () => {
        const paths = (await render()).map((f) => f.path).sort()
        expect(paths).toContain('AGENTS.md')
        expect(paths).toContain('CLAUDE.md')
        expect(paths).toContain('.docs/memory/README.md')
        expect(paths).toContain('.docs/memory/projectState.md')
        expect(paths).toContain('.claude/rules/tiers.md')
        expect(paths).toContain('.claude/rules/conventions.md')
        expect(paths).toContain('.claude/skills/session-start/SKILL.md')
        expect(paths).toContain('.claude/skills/pr-checklist/SKILL.md')
    })

    it('drives AGENTS.md from the config', async () => {
        const agents = (await render()).find((f) => f.path === 'AGENTS.md')?.contents ?? ''
        expect(agents).toContain('# Acme Store — AI Development Foundation')
        expect(agents).toContain('A test storefront.')
        expect(agents).toContain('`main`') // trunk in the branch table
        expect(agents).toContain('`develop`') // integration / protected branch
        expect(agents).toContain('stack pack `node`')
    })

    it('renders configured tier owners and paths into tiers.md', async () => {
        const tiers = (await render()).find((f) => f.path === '.claude/rules/tiers.md')?.contents ?? ''
        expect(tiers).toContain('@acme/leads')
        expect(tiers).toContain('config/**')
        expect(tiers).toContain('frontend')
        expect(tiers).toContain('src/ui/**')
    })

    it('marks memory + CLAUDE.md as create-if-absent (safe for brownfield)', async () => {
        const files = await render()
        expect(files.find((f) => f.path === 'CLAUDE.md')?.merge).toBe('create-if-absent')
        expect(files.find((f) => f.path === '.docs/memory/projectState.md')?.merge).toBe('create-if-absent')
        // AGENTS.md and rule docs are Arche-owned (regenerated)
        expect(files.find((f) => f.path === 'AGENTS.md')?.merge).toBe('replace')
        expect(files.find((f) => f.path === '.claude/rules/tiers.md')?.merge).toBe('replace')
    })

    it('scaffolds git hooks + coderabbit by default and marks hooks executable', async () => {
        const files = await render()
        const paths = files.map((f) => f.path)
        expect(paths).toContain('.githooks/commit-msg')
        expect(paths).toContain('.githooks/pre-commit')
        expect(paths).toContain('coderabbit.yaml')
        expect(files.find((f) => f.path === '.githooks/commit-msg')?.executable).toBe(true)
    })

    it('omits git hooks + coderabbit when their primitives are disabled', async () => {
        const off = parseConfig({
            project: {name: 'X'},
            stackPack: {id: 'node'},
            primitives: {gitHooks: false, staticAnalysis: {coderabbit: false}},
        })
        const paths = (
            await renderProject({config: off, base: templatesBase, pack: emptyPack, cwd: '/tmp/x', archeVersion: '0'})
        ).map((f) => f.path)
        expect(paths).not.toContain('.githooks/commit-msg')
        expect(paths).not.toContain('.githooks/pre-commit')
        expect(paths).not.toContain('coderabbit.yaml')
    })

    it('renders the requirement-spine workflow doc, gated by pmWikiSpine', async () => {
        const on = (await render()).map((f) => f.path)
        expect(on).toContain('.claude/rules/workflow.md')

        const off = parseConfig({project: {name: 'X'}, stackPack: {id: 'node'}, primitives: {pmWikiSpine: false}})
        const offPaths = (
            await renderProject({config: off, base: templatesBase, pack: emptyPack, cwd: '/tmp/x', archeVersion: '0'})
        ).map((f) => f.path)
        expect(offPaths).not.toContain('.claude/rules/workflow.md')
    })

    it('scaffolds the /knowledge skill only when the Shared Brain is enabled', async () => {
        const defaultPaths = (await render()).map((f) => f.path)
        expect(defaultPaths).not.toContain('.claude/skills/knowledge/SKILL.md')

        const on = parseConfig({
            project: {name: 'X'},
            stackPack: {id: 'node'},
            primitives: {sharedBrain: {enabled: true}},
        })
        const onPaths = (
            await renderProject({config: on, base: templatesBase, pack: emptyPack, cwd: '/tmp/x', archeVersion: '0'})
        ).map((f) => f.path)
        expect(onPaths).toContain('.claude/skills/knowledge/SKILL.md')
    })
})

