/**
 * The Arche configuration schema.
 *
 * This is the single authoritative contract for a project's AI-development foundation.
 * Every other package types against the shapes inferred here. The schema is
 * "opinionated defaults, configurable": a minimal config (`project` + `stackPack`) is
 * valid, and everything else is filled in with production-proven defaults.
 *
 * Two derived types matter:
 * - {@link ArcheConfigInput} — what a human writes in `arche.config.ts` (defaults optional).
 * - {@link ArcheConfig} — the fully-resolved config after defaults are applied.
 */

/** A single provider selection. `id: 'none'` disables the provider (degrades to manual steps). */
const baseProviderSchema = z.object({
    /** Provider identifier, e.g. `github`, `gitlab`, `jira`, `confluence`, or `none`. */
    id: z.string().default('none'),
    /** Base URL for self-hosted instances (e.g. GitHub Enterprise, self-managed GitLab). */
    host: z.string().url().optional(),
})

const vcsProviderSchema = baseProviderSchema
    .extend({
        org: z.string().optional(),
        repo: z.string().optional(),
        defaultBranch: z.string().optional(),
    })
    .default({id: 'none'})

const pmProviderSchema = baseProviderSchema
    .extend({
        projectKeys: z.array(z.string()).optional(),
        storyKeyPattern: z.string().optional(),
    })
    .default({id: 'none'})

const wikiProviderSchema = baseProviderSchema
    .extend({
        spaceKey: z.string().optional(),
    })
    .default({id: 'none'})

const providersSchema = z
    .object({
        vcs: vcsProviderSchema,
        pm: pmProviderSchema,
        wiki: wikiProviderSchema,
    })
    .default({})

/** GitFlow-ish branch model — the opinionated default. Every field is overridable. */
const branchModelSchema = z
    .object({
        trunk: z.string().default('main'),
        integration: z.string().default('develop'),
        feature: z.string().default('feature/*'),
        fix: z.string().default('fix/*'),
        release: z.string().default('release/*'),
        hotfix: z.string().default('hotfix/*'),
        /** Branches the AI agent must never commit to directly. */
        agentForbiddenBranches: z.array(z.string()).default(['main', 'develop']),
    })
    .default({})

const commitsSchema = z
    .object({
        convention: z.enum(['conventional', 'none']).default('conventional'),
        /** `'from-registry'` derives allowed scopes from the codebase registry, or pin an explicit list. */
        scopes: z.union([z.literal('from-registry'), z.array(z.string())]).default('from-registry'),
        /** Extra conventional-commit types beyond the standard set (e.g. `upstream-sync`). */
        extraTypes: z.array(z.string()).default([]),
    })
    .default({})

const tier1Schema = z
    .object({
        label: z.string().default('frozen'),
        owners: z.array(z.string()).default([]),
        paths: z.array(z.string()).default([]),
    })
    .default({})

const tier2Schema = z
    .object({
        label: z.string().default('protected'),
        reviewRule: z.enum(['second-dev', 'code-owner']).default('second-dev'),
        owners: z.array(z.string()).default([]),
        paths: z.array(z.string()).default([]),
    })
    .default({})

const squadSchema = z.object({
    paths: z.array(z.string()).default([]),
    owners: z.array(z.string()).default([]),
})

const tier3Schema = z
    .object({
        label: z.string().default('owned'),
        squads: z.record(z.string(), squadSchema).default({}),
    })
    .default({})

const tiersSchema = z
    .object({
        model: z.enum(['three-tier', 'custom']).default('three-tier'),
        tier1: tier1Schema,
        tier2: tier2Schema,
        tier3: tier3Schema,
    })
    .default({})

/** The requirement-ID ↔ story-key ↔ branch ↔ commit ↔ E2E spine. */
const requirementSpineSchema = z
    .object({
        requirementIdPattern: z.string().default('^[A-Z]{2,}-\\d+$'),
        storyKeyPattern: z.string().default('^[A-Z]+-\\d+$'),
        e2eNaming: z
            .object({
                jira: z.string().default('{KEY}_'),
                jiraless: z.string().default('SMOKE-'),
            })
            .default({}),
    })
    .default({})

const staticAnalysisSchema = z
    .object({
        semgrep: z.boolean().default(true),
        astGrep: z.boolean().default(true),
        coderabbit: z.boolean().default(true),
    })
    .default({})

const sharedBrainSchema = z
    .object({
        /** Built in v1, but off by default — needs Postgres + embeddings + a wiki provider. */
        enabled: z.boolean().default(false),
        vectorStore: z.enum(['pgvector']).default('pgvector'),
        embeddingModel: z.string().default('text-embedding-3-small'),
    })
    .default({})

/** Every extension primitive as an explicit on/off. All-on = full v1. */
const primitivesSchema = z
    .object({
        livingMemory: z.boolean().default(true),
        tierHooks: z.boolean().default(true),
        ciWorkflows: z.boolean().default(true),
        codeowners: z.boolean().default(true),
        branchProtection: z.boolean().default(true),
        gitHooks: z.boolean().default(true),
        staticAnalysis: staticAnalysisSchema,
        multiAiPropagation: z.array(z.enum(['cursor', 'copilot', 'windsurf'])).default(['cursor', 'copilot']),
        registry: z.boolean().default(true),
        pmWikiSpine: z.boolean().default(true),
        sharedBrain: sharedBrainSchema,
    })
    .default({})

const projectSchema = z.object({
    name: z.string().min(1),
    description: z.string().optional(),
    /** Whether the human-in-the-lead workflow (checkpointed skills) is enforced. */
    humanInLead: z.boolean().default(true),
})

const stackPackSchema = z.object({
    id: z.string().min(1),
    version: z.string().default('latest'),
})

export const archeConfigSchema = z.object({
    $schemaVersion: z.literal(1).default(1),
    project: projectSchema,
    stackPack: stackPackSchema,
    providers: providersSchema,
    branchModel: branchModelSchema,
    commits: commitsSchema,
    tiers: tiersSchema,
    requirementSpine: requirementSpineSchema,
    primitives: primitivesSchema,
})

/** What a human writes in `arche.config.ts` — all defaulted fields optional. */
export type ArcheConfigInput = z.input<typeof archeConfigSchema>

/** The fully-resolved config after defaults are applied — the machine source of truth. */
export type ArcheConfig = z.infer<typeof archeConfigSchema>

export type ProvidersConfig = ArcheConfig['providers']
export type VcsProviderConfig = ProvidersConfig['vcs']
export type PmProviderConfig = ProvidersConfig['pm']
export type WikiProviderConfig = ProvidersConfig['wiki']
export type BranchModel = ArcheConfig['branchModel']
export type CommitsConfig = ArcheConfig['commits']
export type TierModel = ArcheConfig['tiers']
export type RequirementSpine = ArcheConfig['requirementSpine']
export type Primitives = ArcheConfig['primitives']
","import type {ArcheConfigInput} from './config'

/**
 * Identity helper that gives an `arche.config.ts` author full autocomplete and type
 * checking over the config shape without any runtime cost.
 *
 * @example
 * ```ts
 * import {defineConfig} from '@arche/schema'
 *
 * export default defineConfig({
 *   project: {name: 'acme-store'},
 *   stackPack: {id: 'node'},
 * })
 * ```
 */
export function defineConfig(config: ArcheConfigInput): ArcheConfigInput {
    return config
}
","import {existsSync} from 'node:fs'
import {readFile} from 'node:fs/promises'
import {resolve} from 'node:path'
import {createJiti} from 'jiti'
import {z} from 'zod'
import {archeConfigSchema, type ArcheConfig} from './config'

/** Thrown when a config cannot be found, imported, or validated. */
export class ArcheConfigError extends Error {
    override readonly name = 'ArcheConfigError'
    constructor(
        message: string,
        readonly issues?: z.ZodIssue[],
    ) {
        super(message)
    }
}

const CONFIG_CANDIDATES = [
    'arche.config.ts',
    'arche.config.mts',
    'arche.config.js',
    'arche.config.mjs',
    'arche.config.json',
] as const

/** Validate a raw object against the schema, applying all defaults. Throws on failure. */
export function parseConfig(raw: unknown): ArcheConfig {
    const result = archeConfigSchema.safeParse(raw)
    if (!result.success) {
        const summary = result.error.issues
            .map((i) => `  • ${i.path.join('.') || '(root)'}: ${i.message}`)
            .join('\n')
        throw new ArcheConfigError(`Invalid arche config:\n${summary}`, result.error.issues)
    }
    return result.data
}

/** Non-throwing variant, for callers that want to render their own errors. */
export function safeParseConfig(raw: unknown): z.SafeParseReturnType<unknown, ArcheConfig> {
    return archeConfigSchema.safeParse(raw)
}

/** Find the first `arche.config.*` file in `cwd`, or `undefined` if none exists. */
export function findConfigPath(cwd: string): string | undefined {
    for (const name of CONFIG_CANDIDATES) {
        const candidate = resolve(cwd, name)
        if (existsSync(candidate)) return candidate
    }
    return undefined
}

/** Load and validate the Arche config from `cwd`. Supports `.ts`/`.js`/`.json`. */
export async function loadConfig(cwd: string): Promise<{path: string; config: ArcheConfig}> {
    const path = findConfigPath(cwd)
    if (!path) {
        throw new ArcheConfigError(`No arche.config.{ts,js,json} found in ${cwd}`)
    }
    const raw = path.endsWith('.json')
        ? (JSON.parse(await readFile(path, 'utf8')) as unknown)
        : await importConfigModule(path)
    return {path, config: parseConfig(raw)}
}

async function importConfigModule(path: string): Promise<unknown> {
    const jiti = createJiti(import.meta.url)
    const mod = (await jiti.import(path)) as {default?: unknown}
    return mod?.default ?? mod
}
