import {describe, expect, it} from 'vitest'
import {parseConfig, safeParseConfig} from './loader'

const minimal = {project: {name: 'acme'}, stackPack: {id: 'node'}}

describe('archeConfigSchema', () => {
    it('accepts a minimal config and applies opinionated defaults', () => {
        const config = parseConfig(minimal)

        expect(config.$schemaVersion).toBe(1)
        expect(config.project.name).toBe('acme')
        expect(config.project.humanInLead).toBe(true)
        expect(config.stackPack.version).toBe('latest')
    })

    it('defaults all providers to none (graceful degradation)', () => {
        const config = parseConfig(minimal)
        expect(config.providers.vcs.id).toBe('none')
        expect(config.providers.pm.id).toBe('none')
        expect(config.providers.wiki.id).toBe('none')
    })

    it('defaults to the GitFlow-ish branch model', () => {
        const {branchModel} = parseConfig(minimal)
        expect(branchModel.trunk).toBe('main')
        expect(branchModel.integration).toBe('develop')
        expect(branchModel.agentForbiddenBranches).toEqual(['main', 'develop'])
    })

    it('turns every extension primitive on by default (full v1) except the shared brain', () => {
        const {primitives} = parseConfig(minimal)
        expect(primitives.livingMemory).toBe(true)
        expect(primitives.ciWorkflows).toBe(true)
        expect(primitives.codeowners).toBe(true)
        expect(primitives.staticAnalysis.semgrep).toBe(true)
        expect(primitives.multiAiPropagation).toEqual(['cursor', 'copilot'])
        expect(primitives.sharedBrain.enabled).toBe(false)
    })

    it('defaults to conventional commits with registry-derived scopes', () => {
        const {commits} = parseConfig(minimal)
        expect(commits.convention).toBe('conventional')
        expect(commits.scopes).toBe('from-registry')
    })

    it('respects explicit overrides over defaults', () => {
        const config = parseConfig({
            ...minimal,
            branchModel: {trunk: 'trunk', agentForbiddenBranches: ['trunk']},
            providers: {vcs: {id: 'github', org: 'AcmeCo', repo: 'store'}},
            primitives: {sharedBrain: {enabled: true}},
        })
        expect(config.branchModel.trunk).toBe('trunk')
        expect(config.branchModel.feature).toBe('feature/*') // untouched default preserved
        expect(config.providers.vcs.id).toBe('github')
        expect(config.providers.vcs.org).toBe('AcmeCo')
        expect(config.primitives.sharedBrain.enabled).toBe(true)
    })

    it('rejects a config missing the required project name', () => {
        const result = safeParseConfig({project: {}, stackPack: {id: 'node'}})
        expect(result.success).toBe(false)
    })

    it('rejects a config missing the stack pack', () => {
        const result = safeParseConfig({project: {name: 'acme'}})
        expect(result.success).toBe(false)
    })

    it('throws an ArcheConfigError with readable path info on invalid input', () => {
        expect(() => parseConfig({project: {name: ''}, stackPack: {id: 'node'}})).toThrow(/project\.name/)
    })
})

