import type {RagService} from './rag'

export const KNOWLEDGE_TOOL_NAME = 'query_knowledge'

/**
 * Neutral default knowledge categories. The brain core is taxonomy-agnostic — a deployment
 * passes the labels its wiki provider declares (`requirementSource().pageTypeLabels`) into
 * {@link createKnowledgeTool}; these are only the fallback.
 */
export const DEFAULT_PAGE_TYPES = ['architecture-decision', 'scope-boundary', 'open-item', 'meeting-outcome'] as const

export interface KnowledgeTool {
    name: string
    description: string
    inputSchema: {
        type: 'object'
        properties: {
            question: {type: 'string'; description: string}
            page_type: {type: 'string'; enum: string[]; description: string}
        }
        required: string[]
    }
}

/** Build the `query_knowledge` MCP tool, with `page_type` constrained to the given labels. */
export function createKnowledgeTool(pageTypeLabels: readonly string[] = DEFAULT_PAGE_TYPES): KnowledgeTool {
    return {
        name: KNOWLEDGE_TOOL_NAME,
        description:
            'Query the project shared knowledge base for decisions, scope boundaries, open items, and prior outcomes. Query this before making assumptions about architecture or scope.',
        inputSchema: {
            type: 'object',
            properties: {
                question: {type: 'string', description: 'A specific question to answer from the knowledge base.'},
                page_type: {
                    type: 'string',
                    enum: [...pageTypeLabels],
                    description: 'Optional filter to a single knowledge category.',
                },
            },
            required: ['question'],
        },
    }
}

export interface KnowledgeQueryInput {
    question: string
    page_type?: string
}

export interface KnowledgeResult {
    page_title: string
    page_type: string
    content: string
    source_url?: string
    similarity: number
}

/** Wrap a {@link RagService} as the `query_knowledge` handler (returns MCP-shaped results). */
export function createKnowledgeHandler(rag: RagService) {
    return async (input: KnowledgeQueryInput): Promise<{results: KnowledgeResult[]}> => {
        const scored = await rag.query(input.question, {pageType: input.page_type})
        return {
            results: scored.map((r) => ({
                page_title: r.chunk.pageTitle,
                page_type: r.chunk.pageType,
                content: r.chunk.content,
                source_url: r.chunk.sourceUrl,
                similarity: Number(r.similarity.toFixed(4)),
            })),
        }
    }
}

