import {createKnowledgeHandler, KNOWLEDGE_TOOL, type KnowledgeQueryInput} from './mcp'
import type {RagService} from './rag'

/**
 * Start the `query_knowledge` MCP server over stdio. The MCP SDK is an optional peer — a
 * deployer installs `@modelcontextprotocol/sdk` to run this; it is imported dynamically so
 * `@arche/brain`'s core stays dependency-light and fully testable without it.
 */
export async function startKnowledgeServer(rag: RagService): Promise<void> {
    const handler = createKnowledgeHandler(rag)
    // Variable specifier keeps TS from resolving the optional peer at build time.
    const mcpModule = '@modelcontextprotocol/sdk/server/mcp.js'
    const stdioModule = '@modelcontextprotocol/sdk/server/stdio.js'
    let sdk: {McpServer: new (info: {name: string; version: string}) => McpServerLike}
    let stdio: {StdioServerTransport: new () => unknown}
    try {
        sdk = await import(mcpModule)
        stdio = await import(stdioModule)
    } catch {
        throw new Error('Install @modelcontextprotocol/sdk to run the knowledge MCP server.')
    }

    const server = new sdk.McpServer({name: 'arche-knowledge', version: '0.0.0'})
    server.tool(KNOWLEDGE_TOOL.name, KNOWLEDGE_TOOL.description, async (input: KnowledgeQueryInput) => {
        const result = await handler(input)
        return {content: [{type: 'text', text: JSON.stringify(result, null, 2)}]}
    })
    await server.connect(new stdio.StdioServerTransport())
}

interface McpServerLike {
    tool(name: string, description: string, handler: (input: KnowledgeQueryInput) => Promise<unknown>): void
    connect(transport: unknown): Promise<void>
}

