/**
 * Ask the configured VCS provider for the files it owns (CODEOWNERS + CI workflows), plus the
 * AI-review config, gated by the enabled primitives and the provider's declared capabilities.
 * These are forge-scoped artifacts, so they are only emitted when a VCS provider is present —
 * never from the tech-agnostic base. Returned as {@link VirtualFile}s for the normal plan/apply path.
 */
export async function buildProviderFiles(
    config: ArcheConfig,
    pack: StackPack,
    providers: ProviderSet,
    cwd: string,
): Promise<VirtualFile[]> {
    const vcs = providers.vcs
    if (!vcs) return []
    const ctx: ProviderContext = {config, cwd}
    const files: VirtualFile[] = []

    if (config.primitives.codeowners && vcs.capabilities.has('codeowners')) {
        files.push(vcs.emitCodeowners(config.tiers, ctx))
    }

    if (config.primitives.ciWorkflows && vcs.capabilities.has('ci')) {
        files.push(...vcs.emitCiWorkflows({ci: pack.ci, tier1Paths: config.tiers.tier1.paths}, ctx))
    }

    // AI code review runs on the VCS platform, so it is emitted only alongside a VCS provider.
    if (config.primitives.staticAnalysis.aiReview) {
        files.push(buildCoderabbitConfig(config))
    }

    return files
}

/** CodeRabbit config, forge-neutral. Includes the Claude-Code-provenance heightened-scrutiny rule. */
function buildCoderabbitConfig(config: ArcheConfig): VirtualFile {
    const contents = `# CodeRabbit configuration — generated by Arche for ${config.project.name}.
language: en
reviews:
  profile: assertive
  request_changes_workflow: true
  auto_review:
    enabled: true
  path_instructions:
    - path: "**/*"
      instructions: >-
        Follow the conventions in .claude/rules/. Flag any change that violates the
        file-protection tiers in .claude/rules/tiers.md — Tier 1 changes require code-owner approval.
    - path: "**/*"
      instructions: >-
        CLAUDE-CODE PROVENANCE: if this change appears to be AI-generated (Claude Code), apply
        heightened scrutiny to correctness, error handling, security, and adherence to .claude/rules/.
knowledge_base:
  code_guidelines:
    filePatterns:
      - ".claude/rules/*.md"
      - "AGENTS.md"
`
    return {path: 'coderabbit.yaml', contents, owner: 'arche', merge: 'replace'}
}

