import {applyProject, planProject, type ApplyResult, type ChangePlan, type EngineInput} from '@arche/core'
import type {ActionResult, ActionStatus} from '@arche/kernel'
import {loadConfig} from '@arche/schema'
import type {CliDeps} from '../deps'
import {maybeInstallGitHooks} from '../gitHooks'
import {formatPlan, summarize} from '../output'
import {buildProviderFiles, runServerSideGates} from '../providerFiles'
import {buildRegistryFiles} from '../registry'

export interface ApplyOpts {
    force?: boolean
    write?: boolean
}

/** Resolve config + pack + providers and gather all files (base, pack, provider, registry). */
export async function buildEngineInput(cwd: string, deps: CliDeps): Promise<EngineInput> {
    const {config} = await loadConfig(cwd)
    const pack = await deps.loadPack(config.stackPack.id, cwd)
    const providers = await deps.loadProviders(config, cwd)
    const extraFiles = [
        ...(await buildProviderFiles(config, pack, providers, cwd, deps.version)),
        ...(await buildRegistryFiles(config, pack, cwd)),
    ]
    return {config, base: deps.base, pack, cwd, providers, extraFiles, archeVersion: deps.version}
}

/** `arche plan` — render + diff, no writes. */
export async function runPlan(cwd: string, deps: CliDeps): Promise<ChangePlan> {
    const plan = await planProject(await buildEngineInput(cwd, deps))
    process.stdout.write(`\nArche plan · ${cwd}\n${formatPlan(plan)}\n\n${summarize(plan)}\n`)
    return plan
}

/** `arche apply` — reconcile the working tree, then run the authoritative server-side gates. */
export async function runApply(cwd: string, opts: ApplyOpts, deps: CliDeps): Promise<ApplyResult> {
    const input = await buildEngineInput(cwd, deps)
    const {plan, result} = await applyProject(input, {force: opts.force ?? false, write: opts.write ?? true})
    process.stdout.write(`\nArche apply · ${cwd}\n${formatPlan(plan)}\n\n`)

    if (opts.write !== false) {
        const actions = await runServerSideGates(input.config, input.providers ?? {}, cwd)
        result.providerActions.push(...actions)
        printActions(actions)
        const hooks = await maybeInstallGitHooks(cwd, input.config)
        if (hooks) process.stdout.write(`✓ ${hooks}\n`)
    }

    if (result.conflicts.length > 0) {
        const list = result.conflicts.map((p) => `  - ${p}`).join('\n')
        process.stdout.write(`⚠ ${result.conflicts.length} conflict(s) left untouched. Resolve them, or re-run with --force:\n${list}\n\n`)
    }
    process.stdout.write(`✓ ${result.written.length} written · ${result.skipped.length} unchanged/skipped\n`)
    return result
}

function printActions(actions: ActionResult[]): void {
    if (actions.length === 0) return
    process.stdout.write('Server-side gates (the real Tier 1 enforcement):\n')
    for (const action of actions) {
        process.stdout.write(`  ${statusSymbol(action.status)} ${action.action} — ${action.status}${action.detail ? ` (${action.detail})` : ''}\n`)
        for (const step of action.manualSteps ?? []) process.stdout.write(`      ${step}\n`)
    }
    process.stdout.write('\n')
}

function statusSymbol(status: ActionStatus): string {
    switch (status) {
        case 'applied':
            return '✓'
        case 'unchanged':
            return '='
        case 'failed':
            return '✗'
        case 'unauthenticated':
        case 'unsupported':
            return '⚠'
        default:
            return '·'
    }
}

import {renderProject} from '@arche/core'
import {parseConfig} from '@arche/schema'
import {templatesBase} from '@arche/templates-base'
import {describe, expect, it} from 'vitest'
import {packNode} from './index'

const config = parseConfig({project: {name: 'Acme'}, stackPack: {id: 'node'}})

function render() {
    return renderProject({config, base: templatesBase, pack: packNode, cwd: '/tmp/arche-pack', archeVersion: '0.0.0'})
}

describe('pack-node', () => {
    it('composes node conventions after the base conventions in one doc', async () => {
        const conv = (await render()).find((f) => f.path === '.claude/rules/conventions.md')?.contents ?? ''
        expect(conv).toContain('Apply DRY, KISS') // from base (order 10)
        expect(conv).toContain('TypeScript & Node') // from node pack (order 20)
        expect(conv.indexOf('Apply DRY, KISS')).toBeLessThan(conv.indexOf('TypeScript & Node'))
    })

    it('contributes vitest testing rules', async () => {
        const testing = (await render()).find((f) => f.path === '.claude/rules/testing.md')?.contents ?? ''
        expect(testing).toContain('Vitest (node pack)')
    })

    it('adds pack-owned files (.editorconfig, new-module skill)', async () => {
        const paths = (await render()).map((f) => f.path)
        expect(paths).toContain('.editorconfig')
        expect(paths).toContain('.claude/skills/new-module/SKILL.md')
    })

    it('detects the Arche monorepo as a node project with high confidence', async () => {
        const confidence = await packNode.detect?.(process.cwd())
        expect(confidence).toBeGreaterThan(0.5)
    })

    it('gates semgrep.yml on the staticAnalysis.semgrep flag', async () => {
        const on = (await render()).map((f) => f.path)
        expect(on).toContain('semgrep.yml')

        const off = parseConfig({
            project: {name: 'Acme'},
            stackPack: {id: 'node'},
            primitives: {staticAnalysis: {security: false}},
        })
        const offPaths = (
            await renderProject({config: off, base: templatesBase, pack: packNode, cwd: '/tmp/x', archeVersion: '0'})
        ).map((f) => f.path)
        expect(offPaths).not.toContain('semgrep.yml')
    })
})

