import type {Capability} from '@arche/kernel'
import type {ProviderPlugin, WikiProvider} from '@arche/provider-sdk'
import type {ArcheConfig} from '@arche/schema'

/**
 * The Confluence wiki provider. It declares the page-type labels and template fields the
 * Shared Brain ingests (Phase 8) — a page must carry exactly one type label and the
 * required H2 fields to be ingestible. `fetchRequirements` is intentionally left for the
 * Shared Brain to wire, since it needs `CONFLUENCE_*` credentials.
 */
/** Neutral default knowledge categories; a project overrides via `providers.wiki.pageTypeLabels`. */
const DEFAULT_PAGE_TYPE_LABELS = ['architecture-decision', 'scope-boundary', 'open-item', 'meeting-outcome']

const TEMPLATE_FIELDS = ['Summary', 'Decision / Rule / Outcome', 'Rationale', 'Owner', 'Last Reviewed', 'Related Pages']

export function createConfluenceProvider(config: ArcheConfig): WikiProvider {
    const labels = config.providers.wiki.pageTypeLabels ?? DEFAULT_PAGE_TYPE_LABELS
    return {
        id: 'confluence',
        kind: 'wiki',
        capabilities: new Set<Capability>(['requirement-source']),
        requirementSource() {
            return {pageTypeLabels: [...labels], templateFields: [...TEMPLATE_FIELDS]}
        },
    }
}

const plugin: ProviderPlugin = {id: 'confluence', kind: 'wiki', create: createConfluenceProvider}
export default plugin

import {parseConfig} from '@arche/schema'
import {describe, expect, it} from 'vitest'
import {createConfluenceProvider} from './index'

describe('confluence provider', () => {
    it('exposes neutral default page-type labels and template fields', () => {
        const wiki = createConfluenceProvider(parseConfig({project: {name: 'X'}, stackPack: {id: 'node'}}))
        const source = wiki.requirementSource()
        expect(source.pageTypeLabels).toContain('architecture-decision')
        expect(source.pageTypeLabels).toContain('scope-boundary')
        expect(source.pageTypeLabels).not.toContain('regional-rule') // no e-commerce-specific default
        expect(source.templateFields).toContain('Summary')
        expect(wiki.capabilities.has('requirement-source')).toBe(true)
    })

    it('honors a project-configured page-type label override', () => {
        const wiki = createConfluenceProvider(
            parseConfig({
                project: {name: 'X'},
                stackPack: {id: 'node'},
                providers: {wiki: {id: 'confluence', pageTypeLabels: ['adr', 'runbook']}},
            }),
        )
        expect(wiki.requirementSource().pageTypeLabels).toEqual(['adr', 'runbook'])
    })
})

/**
 * The Shared Brain: a team-wide RAG layer that ingests a wiki's structured knowledge into a
 * vector store and exposes it to Claude via an MCP `query_knowledge` tool. The wiki is
 * abstracted behind {@link WikiPage} and a {@link RequirementSourceSpec}, so any wiki
 * provider can feed it.
 */

/** A page fetched from the wiki, before ingestion. */
export interface WikiPage {
    id: string
    title: string
    /** The page-type label (e.g. `architecture-decision`). */
    type: string
    spaceKey: string
    /** Markdown body with `## <field>` sections. */
    body: string
    url?: string
}

/** A single embedded chunk stored in the vector store. */
export interface KnowledgeChunk {
    id: string
    pageId: string
    pageTitle: string
    pageType: string
    spaceKey: string
    chunkIndex: number
    content: string
    embedding: number[]
    sourceUrl?: string
    checksum: string
}

export interface ScoredChunk {
    chunk: KnowledgeChunk
    similarity: number
}

/** A detected potential contradiction between two chunks — flagged, never auto-resolved. */
export interface ConflictFlag {
    chunkAId: string
    chunkBId: string
    similarity: number
    summary: string
}

/** What the wiki provider declares about ingestible pages (labels + required H2 fields). */
export interface RequirementSourceSpec {
    pageTypeLabels: string[]
    templateFields: string[]
}

