import {checksum, chunkByH2} from './chunker'
import {detectConflicts} from './conflict'
import type {Embedder, VectorStore} from './ports'
import type {ConflictFlag, KnowledgeChunk, RequirementSourceSpec, WikiPage} from './types'

/** Pages must carry these H2 fields to be ingestible (per the Shared Brain page template). */
const REQUIRED_FIELDS = ['Summary', 'Decision / Rule / Outcome']

export interface IngestResult {
    pageId: string
    status: 'success' | 'skipped' | 'malformed'
    chunksWritten: number
    conflicts: ConflictFlag[]
    reason?: string
}

export interface IngestorDeps {
    embedder: Embedder
    store: VectorStore
    source: RequirementSourceSpec
    conflictThreshold?: number
}

export interface Ingestor {
    ingest(page: WikiPage): Promise<IngestResult>
}

/**
 * Validate a page against the wiki's requirement source spec, chunk it by H2, embed the
 * chunks, run conflict detection against the existing store, and upsert. One-way flow:
 * wiki → brain → Claude. Claude never writes back.
 */
export function createIngestor(deps: IngestorDeps): Ingestor {
    return {
        async ingest(page) {
            if (!deps.source.pageTypeLabels.includes(page.type)) {
                return {pageId: page.id, status: 'skipped', chunksWritten: 0, conflicts: [], reason: 'unrecognised page-type label'}
            }
            const raw = chunkByH2(page.body)
            const hasRequired = REQUIRED_FIELDS.every((field) => raw.some((c) => c.heading === field))
            if (!hasRequired) {
                return {
                    pageId: page.id,
                    status: 'malformed',
                    chunksWritten: 0,
                    conflicts: [],
                    reason: `missing required field(s): ${REQUIRED_FIELDS.join(', ')}`,
                }
            }

            const embeddings = await deps.embedder.embed(raw.map((c) => c.content))
            const chunks: KnowledgeChunk[] = raw.map((c, i) => ({
                id: `${page.id}#${c.index}`,
                pageId: page.id,
                pageTitle: page.title,
                pageType: page.type,
                spaceKey: page.spaceKey,
                chunkIndex: c.index,
                content: c.content,
                embedding: embeddings[i] ?? [],
                sourceUrl: page.url,
                checksum: checksum(c.content),
            }))

            const existing = await deps.store.all()
            const conflicts = chunks.flatMap((chunk) => detectConflicts(chunk, existing, {threshold: deps.conflictThreshold}))
            await deps.store.upsert(chunks)
            return {pageId: page.id, status: 'success', chunksWritten: chunks.length, conflicts}
        },
    }
}

